head.b:skin:
/* ============================================================
   OS MY — DARK NAVY E-COMMERCE THEME (v10.0 - FULL ADDRESS + MAPS)
   ============================================================ */
:root {
  --navy-deep:#131921; --navy:#232f3e; --navy-hover:#485769;
  --page-bg:#ffffff; --section-bg:#fafafa; --card:#ffffff;
  --soft:#f3f3f3; --soft-2:#f7f8f8;
  --border:#d5d9d9; --border-strong:#a6a6a6; --border-focus:#e77600;
  --text:#0f1111; --text-2:#565959; --text-3:#767676;
  --link:#007185; --link-hover:#c7511f;
  --price:#0f1111; --price-deal:#b12704; --discount:#cc0c39;
  --btn-yellow:#ffd814; --btn-yellow-hover:#f7ca00; --btn-yellow-border:#fcd200;
  --btn-orange:#ffa41c; --btn-orange-hover:#ff8f00; --btn-orange-border:#ff8f00;
  --star:#ffa41c; --success:#007600; --red:#b12704; --green:#007600;
  --whatsapp:#25d366; --badge-orange:#e08227; --amazon-blue:#00a8e1;
  --promo-green:#067d62; --promo-green-bg:#e8f6ef; --time-badge:#ffd814;
  --header-bg:#ffffff; --header-line:#e6e6e6;
  --shadow-sm:0 1px 2px rgba(15,17,17,.10);
  --shadow-md:0 2px 6px rgba(15,17,17,.15);
  --shadow-lg:0 6px 20px rgba(15,17,17,.25);
  --r-sm:4px; --r:8px; --r-pill:100px; --t:.15s ease;
}
*,*::before,*::after{box-sizing:border-box;-webkit-font-smoothing:antialiased;}
html{width:100%;max-width:100%;scroll-behavior:smooth;}
body{
  font-family:'Cairo',system-ui,-apple-system,'Segoe UI',sans-serif;
  background:var(--page-bg);color:var(--text);margin:0;
  padding:0 0 150px !important;min-height:100vh;
  -webkit-tap-highlight-color:transparent;font-size:14px;direction:rtl;
  touch-action:manipulation;overflow-wrap:break-word;overflow-x:hidden;position:relative;
}
img{max-width:100%;height:auto;display:block;}
button,input,select,textarea{font-family:inherit;outline:none;max-width:100%;}
button{cursor:pointer;background:none;border:none;color:inherit;}
a{text-decoration:none;color:inherit;}
input,textarea,select{color:var(--text);}
.main,.ads-section{width:100%;max-width:100%;overflow:hidden;box-sizing:border-box;}

/* PRELOADER */
#preloader{position:fixed;inset:0;z-index:99999;background:var(--page-bg);display:flex;flex-direction:column;transition:opacity .3s;}
.sk-top{height:60px;background:var(--navy-deep);}
.sk-sub{height:38px;background:var(--navy);}
.sk-grid{padding:14px;display:grid;grid-template-columns:repeat(auto-fill,minmax(180px,1fr));gap:14px;flex:1;}
.sk-card{background:#fff;border:1px solid var(--border);border-radius:var(--r-sm);min-height:280px;animation:shimmer 1.6s ease-in-out infinite;}
@keyframes shimmer{0%,100%{opacity:.45}50%{opacity:1}}

/* HEADER */
header{position:sticky;top:0;z-index:800;background:var(--header-bg);border-bottom:1px solid var(--header-line);box-shadow:var(--shadow-sm);width:100%;max-width:100%;transition:transform 0.3s cubic-bezier(0.4,0,0.2,1);}
header.hide-header{transform:translateY(-100%);}
.h-top{background:var(--header-bg);color:var(--text);display:flex;align-items:center;gap:8px;padding:8px 12px;min-height:56px;flex-wrap:wrap;}
.h-item{display:flex;align-items:center;padding:6px 9px;border-radius:6px;border:1px solid transparent;cursor:pointer;transition:border-color var(--t),background var(--t);user-select:none;flex-shrink:0;}
.h-item:hover{border-color:var(--border);background:var(--soft-2);}
.h-logo{padding:4px 6px;}
.h-logo img{max-height:34px;width:auto;display:block;}
.h-loc{flex-direction:column;line-height:1.15;font-size:12px;}
.h-loc .lbl{color:var(--text-2);font-size:11px;}
.h-loc .val{font-weight:700;font-size:13px;color:var(--text);display:flex;align-items:center;gap:3px;}
.h-loc .val svg{color:var(--badge-orange);}
.h-search{flex:1;min-width:0;display:flex;align-items:stretch;height:42px;border-radius:24px;overflow:hidden;border:1px solid var(--border-strong);transition:border-color var(--t),box-shadow var(--t);background:#fff;align-self:center;}
.h-search:focus-within{border-color:var(--amazon-blue);box-shadow:0 0 0 3px rgba(0,168,225,.22);}
.time-badge{display:flex;align-items:center;gap:5px;background:var(--time-badge);color:var(--text);font-weight:800;font-size:13px;padding:0 14px;height:100%;white-space:nowrap;flex-shrink:0;}
.time-badge svg{color:#a06a00;flex-shrink:0;}
.h-search select{display:none;}
.h-search input{flex:1;min-width:0;border:none;background:#fff;padding:0 14px;font-size:15px;}
.h-search-btn{background:transparent;width:46px;flex-shrink:0;display:grid;place-items:center;transition:background var(--t);}
.h-search-btn:hover{background:var(--soft);}
.h-search-btn svg{color:var(--text-2);}
.h-action{flex-direction:column;line-height:1.15;font-size:12px;}
.h-action .lbl{color:var(--text-2);font-size:11px;font-weight:400;}
.h-action .val{font-weight:700;font-size:13px;color:var(--text);}
.h-cart{gap:4px;}
.h-cart .cart-wrap{position:relative;display:flex;align-items:flex-end;}
.h-cart svg{color:var(--text);}
.h-cart .cart-count{position:absolute;top:-8px;right:-10px;color:var(--badge-orange);font-size:16px;font-weight:800;min-width:18px;text-align:center;line-height:1;}
.h-cart .cart-label{font-weight:700;font-size:13px;color:var(--text);align-self:flex-end;margin-bottom:2px;}
.h-icon-btn{width:38px;height:38px;display:none;align-items:center;justify-content:center;border-radius:6px;border:1px solid transparent;cursor:pointer;position:relative;flex-shrink:0;}
.h-icon-btn:hover{border-color:var(--border);background:var(--soft-2);}
.h-icon-btn svg{color:var(--text);}
.h-icon-btn .badge{position:absolute;top:0;right:0;background:var(--badge-orange);color:#fff;font-size:10px;font-weight:900;padding:1px 5px;border-radius:10px;min-width:16px;text-align:center;line-height:1.3;}
.install-pulse{animation:pulseIcon 2s infinite;}
@keyframes pulseIcon{0%{box-shadow:0 0 0 0 rgba(224,130,39,.5);}70%{box-shadow:0 0 0 8px rgba(224,130,39,0);}100%{box-shadow:0 0 0 0 rgba(224,130,39,0);}}
.suggest-head{padding:12px 14px 2px;font-size:18px;font-weight:800;color:var(--text);}
.h-sub{background:var(--header-bg);color:var(--text);display:flex;align-items:flex-start;padding:8px 10px 10px;overflow-x:auto;scrollbar-width:none;gap:4px;border-bottom:1px solid var(--header-line);}
.h-sub::-webkit-scrollbar{display:none;}
.sub-item{display:flex;flex-direction:column;align-items:center;gap:6px;padding:4px 4px 9px;border:none;width:80px;font-size:12px;font-weight:600;color:var(--text-2);text-align:center;white-space:normal;cursor:pointer;flex-shrink:0;position:relative;transition:color var(--t);}
.sub-ic{width:58px;height:58px;border-radius:50%;background:var(--soft-2);border:1px solid var(--border);display:grid;place-items:center;overflow:hidden;font-size:26px;line-height:1;transition:border-color var(--t),box-shadow var(--t);}
.sub-ic img{width:100%;height:100%;object-fit:cover;}
.sub-item .sub-lbl{display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;line-height:1.25;max-height:30px;}
.sub-item:hover{color:var(--text);}
.sub-item:hover .sub-ic{border-color:var(--border-strong);box-shadow:var(--shadow-sm);}
.sub-item.active{color:var(--text);font-weight:800;}
.sub-item.active .sub-ic{border-color:var(--amazon-blue);box-shadow:0 0 0 2px rgba(0,168,225,.25);}
.sub-item.active::after{content:'';position:absolute;bottom:0;left:16px;right:16px;height:3px;background:var(--amazon-blue);border-radius:3px;}
.sub-item.deals .sub-ic{background:#fff7e6;color:var(--badge-orange);border-color:#ffe0a3;}

/* SEARCH RESULTS BAR */
#search-results-bar{background:#fff;border-bottom:1px solid var(--border);padding:10px 16px;font-size:13px;color:var(--text);display:none;align-items:center;gap:10px;flex-wrap:wrap;}
#search-results-bar.visible{display:flex;}
#search-results-text b{color:var(--price-deal);font-weight:700;}
#clear-search-btn{margin-right:auto;color:var(--link);font-size:13px;cursor:pointer;background:none;border:none;}
#clear-search-btn:hover{color:var(--link-hover);text-decoration:underline;}

/* SORT BAR */
.sort-bar{background:#fff;display:flex;justify-content:space-between;align-items:center;padding:10px 16px;border-bottom:1px solid var(--border);font-size:13px;flex-wrap:wrap;gap:8px;}
#product-count-label{font-weight:700;color:var(--text);}
.sort-select{background:#fff;border:1px solid var(--border-strong);border-radius:var(--r-sm);padding:6px 26px 6px 10px;font-size:13px;cursor:pointer;-webkit-appearance:none;appearance:none;background-image:url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='10' height='6' viewBox='0 0 10 6'><path fill='%23555' d='M0 0l5 6 5-6z'/></svg>");background-repeat:no-repeat;background-position:left 8px center;max-width:100%;text-overflow:ellipsis;}
.sort-select:hover{border-color:var(--border-focus);}

/* PRODUCTS GRID */
.products-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(168px,1fr));gap:12px;padding:14px;max-width:1500px;margin:0 auto;background:var(--page-bg);}
.product-card{background:var(--card);border:1px solid var(--border);border-radius:12px;padding:10px;display:flex;flex-direction:column;position:relative;transition:border-color .15s,box-shadow .15s;}
.product-card:hover{border-color:var(--border-strong);box-shadow:var(--shadow-md);}
.disc-badge{position:absolute;top:8px;left:8px;background:var(--badge-orange);color:#fff;font-size:11px;font-weight:800;padding:4px 8px;border-radius:8px;z-index:2;line-height:1;box-shadow:var(--shadow-sm);}
.new-badge{position:absolute;top:8px;left:8px;background:var(--price-deal);color:#fff;font-size:11px;font-weight:700;padding:4px 8px;border-radius:8px;z-index:2;letter-spacing:.3px;}
.disc-badge + .new-badge{top:34px;}
.wishlist-btn{position:absolute;top:8px;right:8px;background:rgba(255,255,255,.94);border:1px solid var(--border);border-radius:50%;width:30px;height:30px;display:grid;place-items:center;z-index:2;font-size:14px;transition:transform var(--t),border-color var(--t);}
.wishlist-btn:hover{transform:scale(1.1);border-color:var(--border-strong);}
.wishlist-btn.active{background:#fff;border-color:var(--price-deal);}
.card-img-wrap{width:100%;height:140px;display:grid;place-items:center;cursor:pointer;background:#fff;margin-bottom:8px;overflow:hidden;}
.product-card img{max-width:100%;max-height:100%;object-fit:contain;transition:transform .2s ease;}
.product-card:hover img{transform:scale(1.04);}
.product-title{font-size:13px;font-weight:500;margin:0 0 6px;color:var(--text);line-height:1.4;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;cursor:pointer;min-height:36px;}
.product-title:hover{color:var(--link-hover);}
.product-rating{display:flex;align-items:center;gap:5px;margin-bottom:6px;min-height:16px;flex-wrap:wrap;}
.product-rating:empty{display:none;margin:0;}
.stars{color:var(--star);font-size:13px;letter-spacing:-1px;}
.rating-count{font-size:12px;color:var(--link);cursor:pointer;}
.rating-count:hover{color:var(--link-hover);}
.card-foot{display:flex;flex-direction:column;gap:6px;margin-top:auto;}
.price-area{min-width:0;}
.price-row{display:flex;align-items:baseline;gap:4px;margin:0;flex-wrap:wrap;}
.price-currency{font-size:11px;font-weight:500;color:var(--text);}
.price{font-size:19px;font-weight:700;color:var(--text);letter-spacing:-0.3px;line-height:1.1;}
.price.deal{color:var(--text);}
.discount-pct{background:var(--badge-orange);color:#fff;font-size:10px;font-weight:700;padding:2px 5px;border-radius:3px;}
.old-price-row{font-size:11px;color:var(--text-3);margin-top:2px;}
.old-price-row .lbl{display:none;}
.old-price{text-decoration:line-through;}
.btn-quickadd{width:40px;height:40px;flex-shrink:0;align-self:flex-start;border-radius:50%;background:var(--btn-yellow);border:1px solid var(--btn-yellow-border);color:var(--text);font-size:24px;font-weight:700;line-height:1;display:grid;place-items:center;box-shadow:var(--shadow-sm);transition:background var(--t),transform var(--t);font-family:'Cairo',sans-serif;}
.btn-quickadd:hover{background:var(--btn-yellow-hover);transform:scale(1.08);}
.btn-quickadd:active{transform:scale(.92);}

/* INLINE CARD QUANTITY CONTROL */
.cqw-wrap{flex-shrink:0;align-self:flex-start;position:relative;height:40px;width:40px;overflow:hidden;border-radius:40px;background:var(--btn-yellow);border:1px solid var(--btn-yellow-border);box-shadow:var(--shadow-sm);transition:width .24s cubic-bezier(.4,0,.2,1);}
.cqw-wrap.has-qty{width:104px;}
.cqw-btn{position:absolute;inset:0;border-radius:inherit;background:transparent;border:none;color:var(--text);font-size:24px;font-weight:700;display:flex;align-items:center;justify-content:center;cursor:pointer;transition:opacity .16s,transform .16s;font-family:'Cairo',sans-serif;}
.cqw-btn:active{transform:scale(.88);}
.cqw-wrap.has-qty .cqw-btn{opacity:0;transform:scale(.2);pointer-events:none;}
.cqw-pill{position:absolute;top:0;left:0;height:40px;width:104px;display:flex;align-items:center;direction:ltr;opacity:0;pointer-events:none;transition:opacity .18s;}
.cqw-wrap.has-qty .cqw-pill{opacity:1;pointer-events:auto;}
.cqw-inc,.cqw-dec{flex-shrink:0;width:34px;height:40px;border:none;background:transparent;font-size:20px;font-weight:700;color:var(--text);cursor:pointer;display:flex;align-items:center;justify-content:center;font-family:'Cairo',sans-serif;transition:background .12s;}
.cqw-inc:active,.cqw-dec:active{background:rgba(0,0,0,.09);border-radius:40px;}
.cqw-val{flex:1;text-align:center;font-size:15px;font-weight:800;color:var(--text);pointer-events:none;user-select:none;}
@media(max-width:380px){.cqw-wrap.has-qty{width:92px;}.cqw-pill{width:92px;}.cqw-inc,.cqw-dec{width:30px;font-size:18px;}}
.empty-state{grid-column:1/-1;background:#fff;border:1px solid var(--border);border-radius:var(--r-sm);text-align:center;padding:60px 20px;color:var(--text-2);}
.empty-state .icon{font-size:54px;margin-bottom:12px;}
.empty-state h3{font-size:18px;margin:0 0 8px;color:var(--text);font-weight:700;}
.empty-state p{font-size:14px;margin:0;}

/* OFFERS BANNER */
.offers-banner{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:5px;margin:6px 14px 0;padding:24px 16px;border-radius:14px;background:radial-gradient(circle at 50% -10%,#ffc24d,#f0840a 75%);color:#fff;text-align:center;cursor:pointer;box-shadow:var(--shadow-sm);}
.offers-banner .ob-title{font-size:28px;font-weight:900;text-shadow:0 2px 6px rgba(0,0,0,.2);letter-spacing:.5px;}
.offers-banner .ob-sub{font-size:14px;font-weight:700;opacity:.95;}

/* STICKY BOTTOM BAR */
.sticky-bar{position:fixed !important;bottom:0 !important;left:0 !important;right:0 !important;width:100% !important;z-index:999999 !important;display:none;flex-direction:column;box-shadow:0 -4px 15px rgba(0,0,0,0.15);background:#fff;padding-bottom:env(safe-area-inset-bottom);margin:0 !important;}
.sticky-bar.show{display:flex !important;}
.promo-bar{background:var(--promo-green-bg);color:var(--promo-green);display:flex;align-items:center;gap:10px;padding:8px 16px;font-size:12px;line-height:1.4;}
.promo-ring{width:24px;height:24px;flex-shrink:0;border-radius:50%;border:3px solid #bfe3d2;border-top-color:var(--promo-green);}
.promo-text{flex:1;min-width:0;}
.promo-text b{font-weight:800;}
.promo-toggle{color:var(--promo-green);font-weight:700;white-space:nowrap;}
.checkout-bar{background:#fff;border-top:1px solid var(--border);padding:10px 16px;display:flex;justify-content:space-between;align-items:center;gap:12px;cursor:pointer;-webkit-tap-highlight-color:rgba(0,0,0,.04);}
.cart-summary-mini{display:flex;align-items:center;gap:10px;min-width:0;flex:1;}
.cart-summary-mini .mini-thumb{width:42px;height:42px;border-radius:8px;flex-shrink:0;object-fit:contain;background:var(--soft-2);border:1px solid var(--border);}
.sticky-total{font-size:18px;font-weight:800;color:var(--text);line-height:1.1;}
.sticky-count{font-size:12px;color:var(--text-2);}
.sticky-chevron{font-size:20px;color:var(--text-2);flex-shrink:0;transition:transform .24s cubic-bezier(.4,0,.2,1);line-height:1;}
.sticky-bar.sheet-open .sticky-chevron{transform:rotate(180deg);}
.btn-cart-toggle{display:flex;align-items:center;gap:6px;background:var(--btn-yellow);border:1px solid var(--btn-yellow-border);color:var(--text);padding:10px 20px;border-radius:var(--r-pill);font-weight:800;font-size:14px;font-family:'Cairo',sans-serif;cursor:pointer;flex-shrink:0;transition:background var(--t),transform .12s;}
.btn-cart-toggle:hover{background:var(--btn-yellow-hover);}
.btn-cart-toggle:active{transform:scale(.95);}
/* CART REVIEW BOTTOM SHEET */
.cart-sheet{display:none;position:fixed;inset:0;z-index:1000000;background:rgba(15,17,17,.5);align-items:flex-end;justify-content:center;opacity:0;transition:opacity .25s;}
.cart-sheet.show{display:flex !important;opacity:1;}
.cart-sheet.animating{display:flex !important;}
.cart-sheet-panel{background:#fff;width:100%;max-width:500px;border-radius:22px 22px 0 0;display:flex;flex-direction:column;max-height:82vh;transform:translateY(100%);transition:transform .32s cubic-bezier(0,.9,.4,1);overflow:hidden;}
.cart-sheet.show .cart-sheet-panel{transform:translateY(0);}
.cs-handle{display:flex;justify-content:center;padding:10px 0 6px;flex-shrink:0;}
.cs-handle-bar{width:44px;height:4px;background:var(--border-strong);border-radius:10px;}
.cs-head{display:flex;justify-content:space-between;align-items:center;padding:2px 18px 12px;flex-shrink:0;border-bottom:1px solid var(--border);}
.cs-head h3{margin:0;font-size:16px;font-weight:800;color:var(--text);}
.cs-close{background:none;border:1px solid var(--border);border-radius:50%;width:30px;height:30px;font-size:14px;color:var(--text-2);cursor:pointer;display:flex;align-items:center;justify-content:center;transition:background var(--t);}
.cs-close:hover{background:var(--soft-2);}
.cs-body{flex:1;overflow-y:auto;padding:12px;background:var(--page-bg);overscroll-behavior:contain;-webkit-overflow-scrolling:touch;}
.cs-footer{background:#fff;padding:12px 18px;border-top:1px solid var(--border);flex-shrink:0;padding-bottom:calc(12px + env(safe-area-inset-bottom));}
.cs-ship-note{font-size:12px;text-align:center;color:var(--success);font-weight:700;margin-bottom:8px;}
.cs-ship-note.needs-more{color:var(--text-2);}
.cs-totals{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:12px;}
.cs-total-label{font-size:14px;color:var(--text-2);}
.cs-total-val{font-size:22px;font-weight:800;color:var(--price-deal);}
.btn-cs-checkout{width:100%;padding:14px;border-radius:var(--r-pill);background:var(--btn-orange);border:1px solid var(--btn-orange-border);color:var(--text);font-size:16px;font-weight:800;font-family:'Cairo',sans-serif;cursor:pointer;transition:background var(--t),transform .12s;display:flex;align-items:center;justify-content:center;gap:8px;}
.btn-cs-checkout:hover{background:var(--btn-orange-hover);}
.btn-cs-checkout:active{transform:scale(.97);}
/* TWO-PAGE SHEET */
.cs-pages{display:flex;flex-direction:row;width:200%;flex:1;min-height:0;transition:transform .34s cubic-bezier(.4,0,.2,1);}
.cs-pages.on-step2{transform:translateX(-50%);}
.cs-page{width:50%;display:flex;flex-direction:column;flex-shrink:0;min-height:0;overflow:hidden;}
.cs-back{background:none;border:none;color:var(--amazon-blue,#007185);font-size:13px;font-weight:800;cursor:pointer;font-family:'Cairo',sans-serif;display:flex;align-items:center;gap:4px;padding:0;flex-shrink:0;}
.cs-order-summary{background:var(--soft-2);border:1px solid var(--border);border-radius:var(--r-sm);padding:12px;margin-bottom:14px;}
.cs-order-summary-title{font-size:14px;font-weight:800;color:var(--text);margin-bottom:8px;}
.cs-order-item{display:flex;justify-content:space-between;font-size:13px;color:var(--text);padding:5px 0;border-bottom:1px dashed var(--border);}
.cs-order-item:last-child{border-bottom:none;padding-bottom:0;}
.cs-order-total-row{display:flex;justify-content:space-between;font-size:16px;font-weight:800;color:var(--price-deal);padding-top:10px;margin-top:6px;border-top:2px solid var(--border);}
.btn-cs-whatsapp{width:100%;padding:14px;border-radius:var(--r-pill);background:#25d366;border:1px solid #1da851;color:#fff;font-size:16px;font-weight:800;font-family:'Cairo',sans-serif;cursor:pointer;transition:background var(--t),transform .12s;display:flex;align-items:center;justify-content:center;gap:8px;}
.btn-cs-whatsapp:hover{background:#1da851;}
.btn-cs-whatsapp:active{transform:scale(.97);}

/* ZOOM LIGHTBOX */
#zoom-overlay{display:none;position:fixed;inset:0;background:rgba(15,17,17,.92);z-index:99900;justify-content:center;align-items:center;opacity:0;transition:opacity .25s;cursor:zoom-out;}
#zoom-overlay.active{display:flex;opacity:1;}
#zoom-overlay.fading{opacity:0;}
#zoom-img{max-width:92vw;max-height:88vh;object-fit:contain;background:#fff;border-radius:4px;transform-origin:center;transition:transform .2s ease;cursor:grab;user-select:none;-webkit-user-drag:none;box-shadow:0 20px 50px rgba(0,0,0,.5);}
#zoom-img.drag{cursor:grabbing;transition:none;}
#zoom-close{position:fixed;top:14px;right:16px;width:40px;height:40px;background:rgba(255,255,255,.12);border:1px solid rgba(255,255,255,.3);border-radius:50%;color:#fff;font-size:18px;display:flex;align-items:center;justify-content:center;cursor:pointer;z-index:99901;transition:var(--t);}
#zoom-close:hover{background:var(--price-deal);transform:rotate(90deg);}
#zoom-ctrl{position:fixed;bottom:22px;left:50%;transform:translateX(-50%);display:flex;gap:8px;align-items:center;background:rgba(0,0,0,.65);border:1px solid rgba(255,255,255,.2);border-radius:50px;padding:6px 14px;z-index:99901;}
.z-btn{background:rgba(255,255,255,.1);border:none;color:#fff;width:32px;height:32px;border-radius:50%;font-size:16px;display:flex;align-items:center;justify-content:center;cursor:pointer;transition:var(--t);}
.z-btn:hover{background:var(--btn-orange);}
#zoom-pct{color:rgba(255,255,255,.85);font-size:12px;min-width:38px;text-align:center;font-weight:700;}

/* MODALS */
.modal{display:none;position:fixed;inset:0;background:rgba(15,17,17,.55);z-index:15000;justify-content:flex-end;opacity:0;transition:opacity .25s;}
.modal.show{display:flex;opacity:1;}
.modal-panel{background:#fff;width:100%;max-width:440px;height:100%;display:flex;flex-direction:column;transform:translateX(110%);transition:transform .3s cubic-bezier(0,.9,.4,1);overscroll-behavior:none;}
.modal.show .modal-panel{transform:translateX(0);}
.modal-head{background:var(--navy-deep);color:#fff;padding:14px 18px;display:flex;justify-content:space-between;align-items:center;flex-shrink:0;}
.modal-head h2{margin:0;font-size:16px;font-weight:700;}
.modal-close{font-size:16px;color:#fff;background:rgba(255,255,255,.1);border:1px solid rgba(255,255,255,.2);border-radius:50%;width:32px;height:32px;display:flex;align-items:center;justify-content:center;cursor:pointer;transition:var(--t);}
.modal-close:hover{background:var(--price-deal);transform:rotate(90deg);}

/* PRODUCT DRAWER */
#product-modal .modal-panel{max-width:580px;}
.drawer-slider{position:relative;height:340px;flex-shrink:0;background:#fff;border-bottom:1px solid var(--border);}
.drawer-track{display:flex;overflow-x:auto;scroll-snap-type:x mandatory;scroll-behavior:smooth;scrollbar-width:none;height:100%;}
.drawer-track::-webkit-scrollbar{display:none;}
.drawer-slide-img{flex:0 0 100%;width:100%;height:100%;object-fit:contain;scroll-snap-align:center;padding:18px;cursor:zoom-in;}
.drawer-dots{position:absolute;bottom:10px;left:50%;transform:translateX(-50%);display:flex;gap:5px;}
.dot{width:7px;height:7px;border-radius:50%;background:rgba(0,0,0,.25);cursor:pointer;transition:.2s;}
.dot.active{background:var(--btn-orange);width:18px;border-radius:4px;}
.drawer-body{padding:18px;overflow-y:auto;flex:1;background:#fff;overscroll-behavior:contain;}
.drawer-title{font-size:20px;font-weight:500;color:var(--text);margin:0 0 8px;line-height:1.4;}
.rating-line{display:flex;align-items:center;gap:8px;margin-bottom:14px;padding-bottom:14px;border-bottom:1px solid var(--border);min-height:24px;}
.drawer-price-box{padding:0;margin-bottom:16px;}
.drawer-price{font-size:30px;font-weight:400;color:var(--price-deal);line-height:1;display:inline-flex;align-items:baseline;gap:3px;flex-wrap:wrap;}
.drawer-price .currency{font-size:14px;vertical-align:super;font-weight:400;color:var(--text);}
.drawer-old-price{font-size:13px;color:var(--text-2);display:block;margin-top:6px;}
.drawer-old-price .lbl{margin-left:4px;}
.drawer-old-price .old{text-decoration:line-through;}
.drawer-old-price .disc{color:var(--discount);font-weight:700;margin-right:6px;}
.drawer-savings{font-size:13px;color:var(--success);font-weight:700;margin-top:4px;}
.option-group{margin-bottom:14px;padding-bottom:14px;border-bottom:1px solid var(--border);}
.option-label{font-size:14px;font-weight:700;color:var(--text);margin-bottom:8px;}
.option-label span{color:var(--text-2);font-weight:400;margin-right:4px;}
.pills{display:flex;flex-wrap:wrap;gap:8px;}
.pill{background:#fff;border:1px solid var(--border-strong);padding:7px 14px;border-radius:var(--r-sm);font-size:13px;cursor:pointer;color:var(--text);font-family:'Cairo',sans-serif;font-weight:500;transition:var(--t);}
.pill:hover{border-color:var(--border-focus);background:#fff5e6;}
.pill.active{border-color:var(--btn-orange);border-width:2px;padding:6px 13px;background:#fff5e6;box-shadow:0 0 0 2px rgba(255,164,28,.22);}
.delivery-block{background:var(--soft-2);border:1px solid var(--border);border-radius:var(--r-sm);padding:12px;margin:14px 0;font-size:13px;line-height:1.6;}
.delivery-block strong{display:block;font-size:14px;color:var(--text);margin-bottom:4px;}
.delivery-block .free{color:var(--success);font-weight:700;}
.desc-section{margin-top:16px;}
.desc-heading{font-size:15px;font-weight:700;color:var(--text);margin:0 0 8px;padding-bottom:6px;border-bottom:1px solid var(--border);}
.desc-content{font-size:13px;color:var(--text);line-height:1.7;padding:4px 0;}
.desc-content div{padding:3px 0;position:relative;padding-right:18px;}
.desc-content div::before{content:'';position:absolute;right:4px;top:14px;width:4px;height:4px;border-radius:50%;background:var(--text-2);}
.drawer-footer{padding:12px 18px;border-top:1px solid var(--border);background:#fff;display:flex;gap:10px;flex-shrink:0;}
.btn-wishlist-drawer{width:44px;height:44px;border-radius:50%;display:grid;place-items:center;font-size:18px;background:#fff;border:1px solid var(--border-strong);cursor:pointer;transition:var(--t);flex-shrink:0;}
.btn-wishlist-drawer:hover{border-color:var(--price-deal);}
.btn-drawer-add,.btn-drawer-buy{flex:1;height:44px;border-radius:var(--r-pill);font-weight:500;font-size:14px;font-family:'Cairo',sans-serif;cursor:pointer;transition:background var(--t);}
.btn-drawer-add{background:var(--btn-yellow);border:1px solid var(--btn-yellow-border);color:var(--text);}
.btn-drawer-add:hover{background:var(--btn-yellow-hover);}
.btn-drawer-buy{background:var(--btn-orange);border:1px solid var(--btn-orange-border);color:var(--text);}
.btn-drawer-buy:hover{background:var(--btn-orange-hover);}

/* CART */
.cart-body{flex:1;overflow-y:auto;padding:12px;background:var(--page-bg);overscroll-behavior:contain;}
.cart-empty{background:#fff;border:1px solid var(--border);border-radius:var(--r-sm);padding:60px 20px;text-align:center;color:var(--text-2);}
.cart-empty .icon{font-size:48px;margin-bottom:12px;}
.cart-item{background:#fff;border:1px solid var(--border);border-radius:var(--r-sm);padding:14px;display:flex;gap:14px;margin-bottom:10px;}
.cart-item-img{width:90px;height:90px;object-fit:contain;cursor:zoom-in;flex-shrink:0;background:#fff;}
.cart-item-info{flex:1;display:flex;flex-direction:column;gap:4px;min-width:0;}
.cart-item-title{font-size:14px;font-weight:400;color:var(--text);line-height:1.4;}
.cart-item-stock{font-size:12px;color:var(--success);font-weight:600;}
.cart-item-unit{font-size:12px;color:var(--text-2);font-weight:600;margin-top:2px;}
.cart-item-bottom{display:flex;justify-content:space-between;align-items:center;margin-top:8px;gap:8px;flex-wrap:wrap;}
.cart-item-price{font-size:16px;font-weight:800;color:var(--text);white-space:nowrap;}
.cart-qty-ctrl{display:flex;align-items:center;gap:0;background:#fff;border:1px solid var(--btn-yellow-border);border-radius:var(--r-pill);overflow:hidden;box-shadow:var(--shadow-sm);}
.qty-btn{width:32px;height:32px;border-radius:0;background:var(--btn-yellow);border:none;color:var(--text);font-size:17px;font-weight:700;line-height:1;display:flex;align-items:center;justify-content:center;cursor:pointer;transition:background var(--t),transform .12s;font-family:'Cairo',sans-serif;}
.qty-btn:hover{background:var(--btn-yellow-hover);}
.qty-btn:active{transform:scale(.82);}
.qty-val{font-size:14px;font-weight:800;min-width:36px;text-align:center;color:var(--text);user-select:none;animation:qtyPop .18s ease;}
@keyframes qtyPop{0%{transform:scale(.7);opacity:.4;}100%{transform:scale(1);opacity:1;}}
.btn-remove{background:#fff;color:var(--link);border:1px solid var(--border-strong);border-radius:var(--r-sm);padding:4px 10px;cursor:pointer;font-size:12px;font-family:'Cairo',sans-serif;transition:var(--t);}
.btn-remove:hover{background:#f0f8ff;color:var(--link-hover);}
/* CART RECOMMENDED PRODUCTS */
.cart-reco{margin:18px 2px 6px;}
.cart-reco-head{font-size:15px;font-weight:800;color:var(--text);margin-bottom:10px;display:flex;align-items:center;gap:6px;}
.cart-reco-scroll{display:flex;gap:10px;overflow-x:auto;padding-bottom:8px;scroll-snap-type:x proximity;-webkit-overflow-scrolling:touch;scrollbar-width:thin;}
.cart-reco-scroll::-webkit-scrollbar{height:5px;}
.cart-reco-scroll::-webkit-scrollbar-thumb{background:var(--border-strong);border-radius:10px;}
.reco-card{flex:0 0 auto;width:132px;background:#fff;border:1px solid var(--border);border-radius:var(--r-sm);padding:8px;scroll-snap-align:start;display:flex;flex-direction:column;transition:box-shadow var(--t),transform var(--t);}
.reco-card:hover{box-shadow:var(--shadow-md,0 4px 14px rgba(0,0,0,.1));transform:translateY(-2px);}
.reco-card img{width:100%;height:100px;object-fit:contain;background:#fff;border-radius:6px;cursor:pointer;}
.reco-title{font-size:12px;color:var(--text);line-height:1.3;margin:6px 0 4px;height:31px;overflow:hidden;cursor:pointer;}
.reco-price{font-size:13px;font-weight:800;color:var(--price-deal);margin-bottom:7px;}
.reco-add{margin-top:auto;width:100%;padding:7px;border-radius:var(--r-pill);background:var(--btn-yellow);border:1px solid var(--btn-yellow-border);color:var(--text);font-size:12px;font-weight:700;font-family:'Cairo',sans-serif;cursor:pointer;transition:background var(--t),transform .12s;}
.reco-add:hover{background:var(--btn-yellow-hover);}
.reco-add:active{transform:scale(.94);}
.cart-summary{background:#fff;padding:16px 18px;border-top:1px solid var(--border);flex-shrink:0;}
.summary-row{display:flex;justify-content:space-between;font-size:14px;margin-bottom:6px;color:var(--text);}
.summary-row .free-tag{color:var(--success);font-weight:700;}
.summary-total{font-size:18px;font-weight:700;color:var(--price-deal);border-top:1px solid var(--border);padding-top:10px;margin-top:6px;}
.shipping-progress{font-size:12px;color:var(--text-2);text-align:center;margin-bottom:6px;}
.btn-checkout{width:100%;padding:11px;border-radius:var(--r-pill);font-weight:500;font-size:14px;background:var(--btn-yellow);border:1px solid var(--btn-yellow-border);color:var(--text);cursor:pointer;font-family:'Cairo',sans-serif;transition:background var(--t);margin-top:6px;}
.btn-checkout:hover{background:var(--btn-yellow-hover);}
.checkout-form{background:var(--soft-2);border:1px solid var(--border);border-radius:var(--r-sm);padding:14px;margin-top:14px;display:none;}
.checkout-form.show{display:block;}
.checkout-form h4{margin:0 0 10px;font-size:14px;font-weight:700;}
.form-row{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-bottom:8px;}
.loc-wrap{display:flex;gap:8px;margin-bottom:8px;}
.loc-wrap .pro-input{margin-bottom:0;flex:1;}
.btn-location{background:#fff;border:1px solid var(--border-strong);border-radius:var(--r-sm);width:44px;display:grid;place-items:center;font-size:18px;cursor:pointer;transition:var(--t);flex-shrink:0;}
.btn-location:hover{border-color:var(--amazon-blue);background:var(--soft);}
.pro-input{width:100%;padding:10px 12px;border:1px solid var(--border-strong);border-radius:var(--r-sm);font-size:14px;background:#fff;color:var(--text);font-family:'Cairo',sans-serif;transition:var(--t);box-sizing:border-box;display:block;margin-bottom:8px;}
.pro-input:focus{border-color:var(--btn-orange);box-shadow:0 0 0 3px rgba(255,164,28,.22);outline:none;}
textarea.pro-input{resize:vertical;min-height:60px;margin-bottom:0;}
.btn-confirm{background:var(--btn-orange);border:1px solid var(--btn-orange-border);color:var(--text);border-radius:var(--r-pill);font-weight:500;font-size:14px;width:100%;padding:11px;cursor:pointer;font-family:'Cairo',sans-serif;margin-top:10px;display:flex;align-items:center;justify-content:center;gap:8px;transition:background var(--t);}
.btn-confirm:hover:not(:disabled){background:var(--btn-orange-hover);}
#google-auth-container{margin-top:14px;display:flex;justify-content:center;min-height:40px;}
.guest-divider{text-align:center;margin:8px 0;color:var(--text-3);font-size:12px;position:relative;}
.guest-divider::before,.guest-divider::after{content:'';position:absolute;top:50%;width:32%;height:1px;background:var(--border);}
.guest-divider::before{right:0;}
.guest-divider::after{left:0;}
.user-card{background:var(--soft-2);padding:10px 12px;border-radius:var(--r-sm);border:1px solid var(--border);font-size:13px;color:var(--text);display:flex;align-items:center;gap:10px;justify-content:center;margin-bottom:10px;}
.user-card img{width:24px;height:24px;border-radius:50%;}
.user-card .logout-link{color:var(--link);cursor:pointer;font-size:12px;font-weight:700;background:none;border:none;padding:0;}
.user-card .logout-link:hover{color:var(--link-hover);text-decoration:underline;}

/* BOTTOM SHEET */
.bottom-sheet .modal-panel{position:absolute;bottom:0;left:0;right:0;margin:auto;height:auto;width:100%;max-width:500px;border-radius:var(--r) var(--r) 0 0;transform:translateY(110%);transition:transform .3s cubic-bezier(0,.9,.4,1);}
.bottom-sheet.show .modal-panel{transform:translateY(0);}
.sheet-handle{width:40px;height:4px;border-radius:2px;margin:12px auto 0;background:var(--border-strong);}
.contact-list{padding:10px 18px 30px;display:flex;flex-direction:column;gap:10px;overscroll-behavior:contain;}
.contact-item{display:flex;align-items:center;gap:14px;padding:14px;border-radius:var(--r-sm);background:#fff;border:1px solid var(--border);cursor:pointer;transition:var(--t);}
.contact-item:hover{border-color:var(--border-focus);background:#fafafa;}
.contact-icon{font-size:24px;}
.contact-text{font-size:14px;font-weight:700;}

/* HISTORY */
.history-body{flex:1;overflow-y:auto;padding:12px;background:var(--page-bg);overscroll-behavior:contain;}
.history-order{background:#fff;border:1px solid var(--border);border-radius:var(--r-sm);margin-bottom:10px;overflow:hidden;}
.history-order-head{background:#f0f2f2;border-bottom:1px solid var(--border);padding:10px 14px;display:flex;justify-content:space-between;}
.order-id{font-size:11px;color:var(--text-2);}
.order-id b{color:var(--text);font-weight:700;display:block;font-size:13px;margin-top:2px;}
.order-status{font-size:11px;font-weight:700;padding:3px 8px;border-radius:3px;background:rgba(0,118,0,.1);color:var(--success);border:1px solid rgba(0,118,0,.3);align-self:flex-start;}
.order-body-inner{padding:12px 14px;}
.order-date{font-size:12px;color:var(--text-2);margin-bottom:8px;}
.order-item-line{display:flex;justify-content:space-between;font-size:13px;color:var(--text);margin-bottom:4px;}
.order-total-line{display:flex;justify-content:space-between;font-weight:700;font-size:14px;padding-top:8px;border-top:1px solid var(--border);margin-top:8px;}
.order-reorder-btn{margin-top:10px;width:100%;padding:8px;border-radius:var(--r-pill);background:var(--btn-yellow);border:1px solid var(--btn-yellow-border);color:var(--text);font-weight:500;font-size:13px;font-family:'Cairo',sans-serif;cursor:pointer;transition:var(--t);}
.order-reorder-btn:hover{background:var(--btn-yellow-hover);}

/* TOAST */
#toast-wrap{position:fixed;top:16px;left:50%;transform:translateX(-50%);z-index:99999;display:flex;flex-direction:column;gap:8px;width:90%;max-width:340px;pointer-events:none;}
.toast{background:var(--navy-deep);color:#fff;padding:13px 18px;border-radius:var(--r-sm);font-size:14px;text-align:center;font-weight:600;line-height:1.5;box-shadow:var(--shadow-lg);border:1px solid rgba(255,255,255,.1);animation:toastIn .3s forwards;pointer-events:auto;}
.toast.success{background:var(--success);}
.toast.warn{background:var(--price-deal);}
@keyframes toastIn{from{transform:translateY(-14px);opacity:0;}to{transform:translateY(0);opacity:1;}}

/* WISHLIST */
.wl-grid{display:grid;grid-template-columns:repeat(2,1fr);gap:10px;padding:12px;background:var(--page-bg);}
.wl-card{background:#fff;border:1px solid var(--border);border-radius:var(--r-sm);padding:10px;display:flex;flex-direction:column;align-items:center;gap:6px;cursor:pointer;transition:var(--t);}
.wl-card:hover{border-color:var(--border-strong);box-shadow:var(--shadow-sm);}
.wl-img{width:80px;height:80px;object-fit:contain;}
.wl-title{font-size:12px;font-weight:400;text-align:center;color:var(--text);display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden;}
.wl-price{font-size:14px;font-weight:700;color:var(--text);}
.btn-wl-remove{font-size:11px;color:var(--link);background:none;border:none;cursor:pointer;font-family:'Cairo',sans-serif;}
.btn-wl-remove:hover{color:var(--link-hover);text-decoration:underline;}

/* ============================================================
   ADDRESS SYSTEM — NEW
   ============================================================ */

/* First Visit Welcome */
.modal-welcome.bottom-sheet .modal-panel{max-width:480px;}
.welcome-body{padding:32px 24px 24px;text-align:center;flex:1;}
.welcome-icon{font-size:60px;margin-bottom:14px;line-height:1;}
.welcome-title{font-size:22px;font-weight:900;color:var(--text);margin:0 0 10px;}
.welcome-sub{font-size:14px;color:var(--text-2);margin:0 0 28px;line-height:1.65;}
.welcome-btns{display:flex;flex-direction:column;gap:10px;}
.btn-welcome-add{background:var(--btn-yellow);border:1px solid var(--btn-yellow-border);color:var(--text);padding:14px;border-radius:var(--r-pill);font-weight:800;font-size:15px;font-family:'Cairo',sans-serif;cursor:pointer;transition:background var(--t);width:100%;}
.btn-welcome-add:hover{background:var(--btn-yellow-hover);}
.btn-welcome-skip{background:none;border:1px solid var(--border-strong);color:var(--text-2);padding:12px;border-radius:var(--r-pill);font-size:14px;font-family:'Cairo',sans-serif;cursor:pointer;transition:var(--t);width:100%;}
.btn-welcome-skip:hover{color:var(--text);border-color:var(--border-focus);}

/* Add Address Modal */
.add-addr-body{flex:1;overflow-y:auto;padding:16px 18px 30px;overscroll-behavior:contain;}
.addr-type-row{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:14px;}
.addr-type-btn{padding:7px 16px;border:1.5px solid var(--border-strong);border-radius:var(--r-pill);font-size:13px;font-family:'Cairo',sans-serif;cursor:pointer;background:#fff;color:var(--text);transition:var(--t);font-weight:600;}
.addr-type-btn:hover{border-color:var(--btn-orange);color:var(--btn-orange);}
.addr-type-btn.active{background:var(--navy-deep);color:#fff;border-color:var(--navy-deep);}
.loc-row{display:flex;gap:8px;align-items:stretch;margin-bottom:8px;}
.loc-row .pro-input{margin-bottom:0;flex:1;}
.loc-row .btn-location{height:auto;min-height:44px;}
.save-addr-btn{background:var(--btn-orange);border:1px solid var(--btn-orange-border);color:var(--text);border-radius:var(--r-pill);font-weight:700;font-size:15px;width:100%;padding:13px;cursor:pointer;font-family:'Cairo',sans-serif;transition:background var(--t);margin-top:4px;display:flex;align-items:center;justify-content:center;gap:8px;}
.save-addr-btn:hover{background:var(--btn-orange-hover);}

/* Google Maps Picker */
#maps-picker-modal .modal-panel{max-width:100%;}
#map-canvas{width:100%;height:320px;background:var(--soft);position:relative;overflow:hidden;}
.map-placeholder{width:100%;height:100%;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px;background:linear-gradient(135deg,#e8f4ff 0%,#f0f8ff 100%);font-size:14px;color:var(--text-2);}
.map-placeholder .map-icon{font-size:48px;}
.map-addr-bar{padding:12px 16px;background:#fff;border-bottom:1px solid var(--border);border-top:1px solid var(--border);display:flex;align-items:flex-start;gap:10px;min-height:52px;}
.map-addr-bar .map-pin-icon{font-size:20px;flex-shrink:0;margin-top:2px;}
.map-addr-text{flex:1;min-width:0;font-size:13px;color:var(--text);line-height:1.5;}
.map-footer{padding:12px 16px 20px;background:#fff;}
.btn-use-location{width:100%;padding:11px;background:var(--amazon-blue);border:none;color:#fff;border-radius:var(--r-pill);font-weight:700;font-size:14px;font-family:'Cairo',sans-serif;cursor:pointer;margin-bottom:8px;transition:opacity var(--t);}
.btn-use-location:hover{opacity:.88;}
.btn-confirm-map{width:100%;padding:11px;background:var(--btn-yellow);border:1px solid var(--btn-yellow-border);color:var(--text);border-radius:var(--r-pill);font-weight:700;font-size:14px;font-family:'Cairo',sans-serif;cursor:pointer;transition:background var(--t);}
.btn-confirm-map:hover{background:var(--btn-yellow-hover);}

/* Address Selection */
#addr-select-modal .modal-panel{max-width:500px;}
.addr-list-body{flex:1;overflow-y:auto;padding:12px;background:var(--page-bg);overscroll-behavior:contain;}
.addr-card{background:#fff;border:2px solid var(--border);border-radius:var(--r);padding:14px 14px 14px 50px;margin-bottom:10px;cursor:pointer;position:relative;transition:border-color var(--t),box-shadow var(--t);}
.addr-card:hover{border-color:var(--border-strong);}
.addr-card.selected{border-color:var(--amazon-blue);box-shadow:0 0 0 3px rgba(0,168,225,.18);}
.addr-card-radio{position:absolute;top:50%;right:14px;transform:translateY(-50%);width:20px;height:20px;border-radius:50%;border:2px solid var(--border-strong);background:#fff;display:flex;align-items:center;justify-content:center;transition:var(--t);}
.addr-card.selected .addr-card-radio{background:var(--amazon-blue);border-color:var(--amazon-blue);}
.addr-card.selected .addr-card-radio::after{content:'';width:8px;height:8px;border-radius:50%;background:#fff;display:block;}
.addr-type-tag{display:inline-flex;align-items:center;gap:4px;background:#e8f4ff;color:var(--amazon-blue);font-size:11px;font-weight:700;padding:2px 8px;border-radius:var(--r-pill);margin-bottom:6px;}
.addr-card-name{font-size:14px;font-weight:700;color:var(--text);margin-bottom:2px;}
.addr-card-detail{font-size:13px;color:var(--text-2);line-height:1.5;}
.addr-card-phone{font-size:12px;color:var(--text-3);margin-top:2px;}
.addr-card-delete{position:absolute;bottom:10px;left:14px;font-size:11px;color:var(--link);background:none;border:none;cursor:pointer;font-family:'Cairo',sans-serif;padding:2px 0;}
.addr-card-delete:hover{color:var(--price-deal);text-decoration:underline;}
.addr-select-footer{padding:12px 14px;border-top:1px solid var(--border);background:#fff;display:flex;flex-direction:column;gap:8px;flex-shrink:0;}
.btn-add-new-addr{width:100%;padding:11px;border-radius:var(--r-pill);border:1.5px dashed var(--border-strong);background:#fff;color:var(--text-2);font-size:14px;font-family:'Cairo',sans-serif;cursor:pointer;transition:var(--t);}
.btn-add-new-addr:hover{border-color:var(--btn-orange);color:var(--btn-orange);background:#fff8f0;}
.btn-confirm-addr{width:100%;padding:12px;border-radius:var(--r-pill);background:var(--btn-yellow);border:1px solid var(--btn-yellow-border);color:var(--text);font-weight:800;font-size:15px;font-family:'Cairo',sans-serif;cursor:pointer;transition:background var(--t);}
.btn-confirm-addr:hover{background:var(--btn-yellow-hover);}

/* Saved address shown in checkout form */
.selected-addr-preview{background:#e8f4ff;border:1px solid var(--amazon-blue);border-radius:var(--r-sm);padding:10px 12px;font-size:13px;color:var(--text);margin-bottom:8px;display:flex;align-items:flex-start;gap:8px;}
.selected-addr-preview .pin{font-size:16px;flex-shrink:0;}
.selected-addr-preview .change-addr{color:var(--link);font-size:12px;font-weight:700;background:none;border:none;cursor:pointer;padding:0;font-family:'Cairo',sans-serif;margin-top:2px;display:block;}
.selected-addr-preview .change-addr:hover{color:var(--link-hover);}

/* Focus a11y */
button:focus-visible,.pill:focus-visible,.h-item:focus-visible{outline:2px solid var(--btn-orange);outline-offset:2px;}

/* RESPONSIVE */
@media (max-width:780px){
  .h-top{flex-wrap:wrap;padding:8px 10px;justify-content:space-between;gap:8px;}
  .h-logo{order:1;margin-left:auto;}
  .h-action-desktop{display:none;}
  .h-mobile-icons{order:2;display:flex;gap:4px;}
  .h-cart{order:3;}
  .h-cart .cart-label{display:none;}
  .h-search{order:4;width:100%;flex-basis:100%;height:42px;margin-top:4px;}
  .h-loc{order:5;width:100%;flex-direction:row;gap:6px;font-size:12px;background:var(--soft-2);padding:8px 10px;border-radius:6px;justify-content:flex-start;margin-top:4px;}
  .products-grid{grid-template-columns:repeat(2,1fr);padding:10px;gap:10px;}
  .product-card{padding:8px;border-radius:10px;}
  .card-img-wrap{height:130px;margin-bottom:6px;}
  .product-title{font-size:12px;min-height:34px;margin-bottom:4px;}
  .price{font-size:16px;}
  .btn-quickadd{width:34px;height:34px;font-size:20px;}
  .modal-panel,#product-modal .modal-panel,.bottom-sheet .modal-panel{max-width:100%;width:100%;}
  .drawer-slider{height:260px;}
  .drawer-title{font-size:18px;}
  .drawer-price{font-size:24px;}
  .drawer-footer{padding:10px;gap:6px;}
  .btn-drawer-add,.btn-drawer-buy{height:40px;font-size:13px;}
  .cart-item{padding:10px;gap:10px;flex-wrap:wrap;}
  .cart-item-img{width:70px;height:70px;}
  .form-row{grid-template-columns:1fr;gap:8px;}
  .offers-banner{padding:16px;margin:8px;}
  .offers-banner .ob-title{font-size:22px;}
  #map-canvas{height:260px;}
}
@media (max-width:380px){
  .products-grid{padding:6px;gap:6px;}
  .product-card{padding:6px;border-radius:8px;}
  .card-img-wrap{height:110px;}
  .product-title{font-size:11px;min-height:32px;}
  .price{font-size:14px;}
  .price-currency{font-size:10px;}
  .btn-quickadd{width:30px;height:30px;font-size:18px;}
  .card-foot{gap:4px;} .cqw-wrap.has-qty{width:92px;} .cqw-pill{width:92px;}
  .time-badge{padding:0 6px;font-size:11px;}
  .h-search input{padding:0 10px;font-size:13px;}
  .h-search-btn{width:38px;}
}

body.script:
//

/* ============================================================
   SMART HEADER HIDE/SHOW ON SCROLL
   ============================================================ */
var lastScrollY = window.scrollY || document.documentElement.scrollTop;
var headerEl = document.querySelector('header');
window.addEventListener('scroll', function() {
  var cur = window.scrollY || document.documentElement.scrollTop;
  if (cur > lastScrollY && cur > 60) { headerEl.classList.add('hide-header'); }
  else { headerEl.classList.remove('hide-header'); }
  lastScrollY = cur <= 0 ? 0 : cur;
}, { passive: true });

/* ============================================================
   STORE CONFIG
   ============================================================ */
var CONFIG = {
  currency: 'ر.س',
  whatsapp: '18292147994',
  phone: '+18292147994',
  storeName: 'Os My',
  freeShippingMin: 200,
  shippingFee: 25,
  feedCacheKey: 'sp_feed_cache_v3',
  feedCacheTTL: 300000,
  defaultCategory: 'الكل',
  mapsApiKey: 'YOUR_GOOGLE_MAPS_API_KEY'
};

/* ============================================================
   PWA INSTALL
   ============================================================ */
var deferredInstallPrompt = null;
var installBtn = document.getElementById('installAppBtn');
function isAppInstalled() {
  return window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone === true;
}
window.addEventListener('beforeinstallprompt', function(e) {
  e.preventDefault(); deferredInstallPrompt = e;
  if (installBtn && !isAppInstalled()) installBtn.style.display = 'flex';
});
function promptAppInstall() {
  if (deferredInstallPrompt) {
    deferredInstallPrompt.prompt();
    deferredInstallPrompt.userChoice.then(function(c) {
      if (c.outcome === 'accepted' && installBtn) installBtn.style.display = 'none';
      deferredInstallPrompt = null;
    });
  } else {
    var isIOS = /iPad|iPhone|iPod/.test(navigator.userAgent) && !window.MSStream;
    if (isIOS) toast('🍎 للتثبيت: اضغط زر المشاركة ⤴ ثم "إضافة إلى الشاشة الرئيسية"','',7);
    else toast('🤖 للتثبيت: افتح قائمة المتصفح ⋮ ثم اختر "إضافة للشاشة الرئيسية"','',7);
  }
}
window.addEventListener('DOMContentLoaded', function() {
  if (isAppInstalled()) { if (installBtn) installBtn.style.display = 'none'; }
  else { var isIOS = /iPad|iPhone|iPod/.test(navigator.userAgent) && !window.MSStream; if (isIOS && installBtn) installBtn.style.display = 'flex'; }
  document.querySelectorAll('.modal').forEach(function(m) {
    m.addEventListener('touchmove', function(e) { if (e.target === m) e.preventDefault(); }, { passive: false });
  });
});

/* ============================================================
   MULTI-TAB SYNC
   ============================================================ */
var BC = (typeof BroadcastChannel !== 'undefined') ? new BroadcastChannel('sp_store_sync') : null;
if (BC) {
  BC.onmessage = function(ev) {
    var t = ev.data && ev.data.type, p = ev.data && ev.data.payload;
    if (t === 'cart')     { cart = p; saveCartLocal(); updateCartUI(); }
    if (t === 'wishlist') { wishlist = p; wishlistSet = new Set(p); saveWishlistLocal(); updateWishlistBadge(); applyAllFilters(); }
    if (t === 'history')  { orderHistory = p; saveHistoryLocal(); }
    if (t === 'addrs')    { savedAddresses = p; updateDeliveryDisplay(); }
  };
}
window.addEventListener('storage', function(ev) {
  try {
    if (ev.key === 'sp_cart_v5')  { cart = JSON.parse(ev.newValue) || []; updateCartUI(); }
    if (ev.key === 'sp_wl_v5')    { wishlist = JSON.parse(ev.newValue) || []; wishlistSet = new Set(wishlist); updateWishlistBadge(); applyAllFilters(); }
    if (ev.key === 'sp_hist_v5')  { orderHistory = JSON.parse(ev.newValue) || []; }
    if (ev.key === 'sp_addrs_v1') { savedAddresses = JSON.parse(ev.newValue) || []; updateDeliveryDisplay(); }
  } catch(e) {}
});
function broadcast(type, payload) { if (BC) BC.postMessage({ type: type, payload: payload }); }

/* ============================================================
   STATE
   ============================================================ */
var products = [];
var productIndex = {};
var cart = [];
var wishlist = [];
var wishlistSet = new Set();
var orderHistory = [];
var allCategories = new Set();
var currentCat = CONFIG.defaultCategory;
var searchQuery = '';
var sortMode = 'default';
var currentDrawerProduct = null;
var currentDrawerSelected = {};
var renderedIds = [];
var searchDebounce = null;
var drawerOpen = false;
var currentUser = null;
var wishlistVersion = 0;
var discountCache = {};
var starsCache = {};

/* ADDRESS STATE */
var savedAddresses = [];
var selectedAddressIndex = 0;
var currentAddrType = '🏠 المنزل';
var addAddrReturnCtx = null;   // null | 'checkout' | 'addr-select-modal'
var pendingMapLocation = null; // { lat, lng, formatted, city, district }

/* MAPS STATE */
var gmapsState = 'idle'; // idle | loading | ready | error
var gmapsQueue = [];
var mapInstance = null;
var mapMarker = null;
var mapGeocoder = null;

/* CHECKOUT STATE */
var checkoutFormVisible = false;
var checkoutPrefillAddr = null;

/* ============================================================
   LOAD STATE FROM STORAGE
   ============================================================ */
function loadState() {
  try { var c = JSON.parse(localStorage.getItem('sp_cart_v5')); if (Array.isArray(c)) cart = c.filter(function(i){ return i && i.id; }); } catch(e) {}
  try { var w = JSON.parse(localStorage.getItem('sp_wl_v5'));   if (Array.isArray(w)) { wishlist = w; wishlistSet = new Set(w); } } catch(e) {}
  try { var h = JSON.parse(localStorage.getItem('sp_hist_v5')); if (Array.isArray(h)) orderHistory = h; } catch(e) {}
  try { var u = JSON.parse(localStorage.getItem('sp_user_v5')); if (u && u.email) currentUser = u; } catch(e) {}
  loadAddresses();
}
loadState();

function saveCartLocal()     { localStorage.setItem('sp_cart_v5', JSON.stringify(cart)); }
function saveWishlistLocal() { localStorage.setItem('sp_wl_v5',   JSON.stringify(wishlist)); }
function saveHistoryLocal()  { localStorage.setItem('sp_hist_v5', JSON.stringify(orderHistory)); }
function saveCart()     { saveCartLocal();     broadcast('cart', cart); }
function saveWishlist() { saveWishlistLocal(); broadcast('wishlist', wishlist); wishlistVersion++; }
function saveHistory()  { saveHistoryLocal();  broadcast('history', orderHistory); }

/* ============================================================
   ADDRESS MANAGEMENT
   ============================================================ */
function loadAddresses() {
  try {
    var a = JSON.parse(localStorage.getItem('sp_addrs_v1') || '[]');
    if (Array.isArray(a)) savedAddresses = a;
    var idx = parseInt(localStorage.getItem('sp_addrs_sel') || '0', 10);
    selectedAddressIndex = isNaN(idx) ? 0 : Math.max(0, Math.min(idx, savedAddresses.length - 1));
  } catch(e) { savedAddresses = []; selectedAddressIndex = 0; }

  // Legacy migration: absorb old sp_addr_v5 if no addresses yet
  if (savedAddresses.length === 0) {
    try {
      var old = JSON.parse(localStorage.getItem('sp_addr_v5'));
      if (old && old.city) {
        savedAddresses.push({ id: 'addr_legacy', label: '🏠 المنزل', name: '', phone: '', city: old.city || '', district: old.district || '', street: old.street || '', formatted: [old.street, old.district, old.city].filter(Boolean).join('، ') });
        persistAddresses();
      }
    } catch(e) {}
  }
  updateDeliveryDisplay();
}

function persistAddresses() {
  localStorage.setItem('sp_addrs_v1', JSON.stringify(savedAddresses));
  localStorage.setItem('sp_addrs_sel', String(selectedAddressIndex));
  broadcast('addrs', savedAddresses);
}

function updateDeliveryDisplay() {
  var dc = document.getElementById('delivery-city');
  if (!dc) return;
  if (savedAddresses.length > 0 && savedAddresses[selectedAddressIndex]) {
    var a = savedAddresses[selectedAddressIndex];
    dc.textContent = a.city + (a.district ? '، ' + a.district : '');
  }
}

function checkFirstVisit() {
  var seen = localStorage.getItem('sp_visited_v2');
  if (!seen) {
    localStorage.setItem('sp_visited_v2', '1');
    if (savedAddresses.length === 0) {
      setTimeout(function() { openModal('first-visit-modal'); }, 1800);
    }
  }
}

/* Address type selector */
function selectAddrType(el, label) {
  document.querySelectorAll('.addr-type-btn').forEach(function(b) { b.classList.remove('active'); });
  el.classList.add('active');
  currentAddrType = label;
}

/* Open add-address modal with optional return context */
function openAddAddrModal(returnCtx) {
  addAddrReturnCtx = returnCtx || null;
  pendingMapLocation = null;
  // Reset fields
  ['na-city','na-district','na-street','na-name','na-phone'].forEach(function(id) {
    var el = document.getElementById(id); if (el) el.value = '';
  });
  // Pre-fill name from Google account
  var nameEl = document.getElementById('na-name');
  if (nameEl && currentUser && !nameEl.value) nameEl.value = currentUser.name || '';
  // Reset type buttons
  document.querySelectorAll('.addr-type-btn').forEach(function(b, i) { b.classList.toggle('active', i === 0); });
  currentAddrType = '🏠 المنزل';
  openModal('add-addr-modal');
}

function closeAddAddrModal() {
  closeModal('add-addr-modal');
}

function saveNewAddress() {
  var city     = (document.getElementById('na-city')     || {}).value.trim() || '';
  var district = (document.getElementById('na-district') || {}).value.trim() || '';
  var street   = (document.getElementById('na-street')   || {}).value.trim() || '';
  var name     = (document.getElementById('na-name')     || {}).value.trim() || '';
  var phone    = (document.getElementById('na-phone')    || {}).value.trim() || '';

  // If GPS was used without manual city entry, extract from pending
  if (!city && pendingMapLocation && pendingMapLocation.city) city = pendingMapLocation.city;
  if (!street && pendingMapLocation && pendingMapLocation.formatted) street = pendingMapLocation.formatted;

  if (!city) { toast('يرجى إدخال اسم المدينة', 'warn'); return; }
  if (!name) { toast('يرجى إدخال اسم المستلم', 'warn'); return; }
  if (!phone) { toast('يرجى إدخال رقم جوال المستلم', 'warn'); return; }

  var addr = {
    id: 'addr_' + Date.now(),
    label: currentAddrType,
    name: name,
    phone: phone,
    city: city,
    district: district,
    street: street,
    lat: pendingMapLocation ? pendingMapLocation.lat : null,
    lng: pendingMapLocation ? pendingMapLocation.lng : null,
    formatted: [street, district, city].filter(Boolean).join('، ')
  };

  savedAddresses.push(addr);
  selectedAddressIndex = savedAddresses.length - 1;
  persistAddresses();
  updateDeliveryDisplay();
  closeAddAddrModal();
  toast('تم حفظ العنوان بنجاح ✅', 'success');

  // Route back to the caller
  var ctx = addAddrReturnCtx;
  addAddrReturnCtx = null;
  if (ctx === 'addr-select-modal') {
    setTimeout(function() { renderAddrList(); openModal('addr-select-modal'); }, 360);
  } else if (ctx === 'checkout') {
    setTimeout(function() { openModal('cart-modal'); setTimeout(function() { showCartCheckoutForm(addr); }, 420); }, 360);
  }
}

function deleteAddress(id) {
  savedAddresses = savedAddresses.filter(function(a) { return a.id !== id; });
  if (selectedAddressIndex >= savedAddresses.length) selectedAddressIndex = Math.max(0, savedAddresses.length - 1);
  persistAddresses();
  updateDeliveryDisplay();
  renderAddrList();
  toast('تم حذف العنوان', 'warn');
}

function selectAddressCard(idx) {
  selectedAddressIndex = idx;
  persistAddresses();
  renderAddrList();
}

function renderAddrList() {
  var body = document.getElementById('addr-list-body');
  if (!body) return;
  if (!savedAddresses.length) {
    body.innerHTML = '<div class="empty-state"><div class="icon">📍</div><h3>لا توجد عناوين محفوظة</h3><p>أضف عنواناً للتوصيل</p></div>';
    return;
  }
  var html = '';
  for (var i = 0; i < savedAddresses.length; i++) {
    var a = savedAddresses[i];
    var sel = (i === selectedAddressIndex);
    var detail = [a.street, a.district, a.city].filter(Boolean).join('، ');
    html += '<div class="addr-card' + (sel ? ' selected' : '') + '" onclick="selectAddressCard(' + i + ')">'
      + '<div class="addr-card-radio"></div>'
      + '<div class="addr-type-tag">' + (a.label || '📍 عنوان') + '</div>'
      + '<div class="addr-card-name">' + escapeHtml(a.name) + '</div>'
      + (detail ? '<div class="addr-card-detail">' + escapeHtml(detail) + '</div>' : '')
      + (a.phone ? '<div class="addr-card-phone">📞 ' + escapeHtml(a.phone) + '</div>' : '')
      + '<button class="addr-card-delete" onclick="event.stopPropagation();deleteAddress(\'' + a.id + '\')">حذف ✕</button>'
      + '</div>';
  }
  body.innerHTML = html;
}

function confirmSelectedAddress() {
  if (!savedAddresses.length) { toast('يرجى إضافة عنوان أولاً', 'warn'); return; }
  if (selectedAddressIndex >= savedAddresses.length) selectedAddressIndex = 0;
  persistAddresses();
  var addr = savedAddresses[selectedAddressIndex];
  closeModal('addr-select-modal');
  setTimeout(function() {
    var cartModal = document.getElementById('cart-modal');
    if (cartModal && cartModal.classList.contains('show')) {
      showCartCheckoutForm(addr);
    } else {
      openModal('cart-modal');
      setTimeout(function() { showCartCheckoutForm(addr); }, 420);
    }
  }, 360);
}

/* Show checkout form inside cart modal, pre-filled with address */
function showCartCheckoutForm(addr) {
  checkoutFormVisible = true;
  checkoutPrefillAddr = addr || null;
  var subtotal = cart.reduce(function(s,i) { return s + i.price * i.qty; }, 0);
  renderCartBody(subtotal);
}

/* Entry-point when user clicks checkout button */
function showCheckoutFlow() {
  if (!cart.length) return;
  if (savedAddresses.length > 0) {
    renderAddrList();
    openModal('addr-select-modal');
  } else {
    openAddAddrModal('checkout');
  }
}

/* Legacy saveAddress() kept for the old #address-modal */
function saveAddress() {
  var city     = (document.getElementById('addr-city')     || {}).value.trim() || '';
  var district = (document.getElementById('addr-district') || {}).value.trim() || '';
  var street   = (document.getElementById('addr-street')   || {}).value.trim() || '';
  if (!city) { toast('أدخل المدينة','warn'); return; }
  localStorage.setItem('sp_addr_v5', JSON.stringify({ city: city, district: district, street: street }));
  // Also push into new system
  var dup = savedAddresses.some(function(a) { return a.city === city && a.district === district && a.street === street; });
  if (!dup) {
    savedAddresses.push({ id: 'addr_' + Date.now(), label: '🏠 المنزل', name: currentUser ? (currentUser.name || '') : '', phone: '', city: city, district: district, street: street, formatted: [street, district, city].filter(Boolean).join('، ') });
    selectedAddressIndex = savedAddresses.length - 1;
    persistAddresses();
  }
  updateDeliveryDisplay();
  closeModal('address-modal');
  toast('تم حفظ العنوان ✅','success');
}

/* ============================================================
   GOOGLE MAPS INTEGRATION
   ============================================================ */
function requireGoogleMaps(cb) {
  if (gmapsState === 'ready') { cb(); return; }
  gmapsQueue.push(cb);
  if (gmapsState === 'loading') return;
  gmapsState = 'loading';
  window.__gmapsReadyCB = function() {
    gmapsState = 'ready';
    var q = gmapsQueue.splice(0);
    q.forEach(function(fn) { try { fn(); } catch(e) {} });
  };
  var s = document.createElement('script');
  s.src = 'https://maps.googleapis.com/maps/api/js?key=' + CONFIG.mapsApiKey + '&callback=__gmapsReadyCB&language=ar&region=SA';
  s.async = true; s.defer = true;
  s.onerror = function() {
    gmapsState = 'error';
    gmapsQueue = [];
    var ph = document.getElementById('map-placeholder');
    if (ph) ph.innerHTML = '<div class="map-icon">⚠️</div><div>تعذّر تحميل الخريطة</div><div style="font-size:12px">تحقّق من مفتاح API أو الاتصال بالإنترنت</div>';
    toast('تعذّر تحميل الخريطة. يمكنك إدخال العنوان يدوياً.', 'warn');
  };
  document.head.appendChild(s);
}

function openMapsModal() {
  pendingMapLocation = null;
  var addrText = document.getElementById('map-addr-text');
  if (addrText) addrText.textContent = 'انقر على الخريطة لتحديد موقعك...';
  openModal('maps-picker-modal');
  requireGoogleMaps(function() { setTimeout(initMapPicker, 150); });
}

function closeMapsModal() { closeModal('maps-picker-modal'); }

function initMapPicker() {
  var canvas = document.getElementById('map-canvas');
  if (!canvas || !window.google || !google.maps) return;
  if (mapInstance) {
    google.maps.event.trigger(mapInstance, 'resize');
    return;
  }
  // Remove placeholder
  var ph = document.getElementById('map-placeholder');
  if (ph) ph.remove();

  var center = { lat: 24.7136, lng: 46.6753 }; // Riyadh default
  mapInstance = new google.maps.Map(canvas, {
    center: center, zoom: 13,
    streetViewControl: false, mapTypeControl: false,
    fullscreenControl: false, gestureHandling: 'greedy'
  });
  mapGeocoder = new google.maps.Geocoder();
  mapMarker = new google.maps.Marker({ map: mapInstance, draggable: true, animation: google.maps.Animation.DROP });

  mapInstance.addListener('click', function(e) {
    placeMapPin(e.latLng.lat(), e.latLng.lng());
  });
  mapMarker.addListener('dragend', function(e) {
    doReverseGeocode(e.latLng.lat(), e.latLng.lng());
  });

  // Auto-center on user location
  if (navigator.geolocation) {
    navigator.geolocation.getCurrentPosition(function(pos) {
      var ll = { lat: pos.coords.latitude, lng: pos.coords.longitude };
      mapInstance.setCenter(ll); mapInstance.setZoom(15);
      placeMapPin(ll.lat, ll.lng);
    }, function() {});
  }
}

function placeMapPin(lat, lng) {
  if (!mapMarker) return;
  var ll = new google.maps.LatLng(lat, lng);
  mapMarker.setPosition(ll);
  mapInstance.panTo(ll);
  doReverseGeocode(lat, lng);
}

function doReverseGeocode(lat, lng) {
  pendingMapLocation = { lat: lat, lng: lng, formatted: 'موقع GPS: ' + lat.toFixed(5) + ', ' + lng.toFixed(5), city: '', district: '' };
  var addrText = document.getElementById('map-addr-text');
  if (addrText) addrText.textContent = 'جاري تحديد العنوان...';
  if (!mapGeocoder) {
    if (addrText) addrText.textContent = pendingMapLocation.formatted;
    return;
  }
  mapGeocoder.geocode({ location: { lat: lat, lng: lng }, language: 'ar' }, function(results, status) {
    if (status === 'OK' && results && results[0]) {
      var formatted = results[0].formatted_address;
      pendingMapLocation.formatted = formatted;
      if (addrText) addrText.textContent = formatted;
      // Extract city & district from address components
      var comps = results[0].address_components || [];
      comps.forEach(function(c) {
        if (c.types.indexOf('locality') >= 0 || c.types.indexOf('administrative_area_level_2') >= 0) {
          if (!pendingMapLocation.city) pendingMapLocation.city = c.long_name;
        }
        if (c.types.indexOf('sublocality') >= 0 || c.types.indexOf('neighborhood') >= 0) {
          if (!pendingMapLocation.district) pendingMapLocation.district = c.long_name;
        }
      });
    } else {
      if (addrText) addrText.textContent = pendingMapLocation.formatted;
    }
  });
}

function useCurrentGPS() {
  var addrText = document.getElementById('map-addr-text');
  if (!navigator.geolocation) { toast('المتصفح لا يدعم تحديد الموقع', 'warn'); return; }
  if (addrText) addrText.textContent = 'جاري تحديد موقعك...';
  navigator.geolocation.getCurrentPosition(function(pos) {
    var lat = pos.coords.latitude, lng = pos.coords.longitude;
    if (mapInstance && mapMarker) {
      placeMapPin(lat, lng);
      mapInstance.setZoom(16);
    } else {
      pendingMapLocation = { lat: lat, lng: lng, formatted: 'https://maps.google.com/?q=' + lat + ',' + lng, city: '', district: '' };
      if (addrText) addrText.textContent = 'موقعك: ' + lat.toFixed(4) + ', ' + lng.toFixed(4);
      toast('تم تحديد موقعك ✅', 'success');
    }
  }, function() { toast('تعذّر تحديد الموقع. يرجى الإدخال يدوياً.', 'warn'); if (addrText) addrText.textContent = 'انقر على الخريطة لتحديد موقعك...'; });
}

function confirmMapLocation() {
  if (!pendingMapLocation) { toast('يرجى تحديد موقعك على الخريطة أولاً', 'warn'); return; }
  // Fill address form fields
  var cityEl     = document.getElementById('na-city');
  var districtEl = document.getElementById('na-district');
  var streetEl   = document.getElementById('na-street');
  if (cityEl     && pendingMapLocation.city)      cityEl.value     = pendingMapLocation.city;
  if (districtEl && pendingMapLocation.district)  districtEl.value = pendingMapLocation.district;
  if (streetEl   && pendingMapLocation.formatted) streetEl.value   = pendingMapLocation.formatted;
  closeMapsModal();
  toast('تم تحديد الموقع ✅', 'success');
}

/* Also support GPS button inside checkout form */
function getLocation() {
  var sheetOnStep2 = (function() {
    var sh = document.getElementById('cart-sheet'), pg = document.getElementById('cs-pages');
    return sh && sh.classList.contains('show') && pg && pg.classList.contains('on-step2');
  })();
  var addrInput = document.getElementById(sheetOnStep2 ? 'cs-c-addr' : 'c-addr');
  if (!navigator.geolocation) { toast('المتصفح لا يدعم تحديد الموقع', 'warn'); return; }
  if (addrInput) addrInput.placeholder = 'جاري تحديد الموقع... ⏳';
  navigator.geolocation.getCurrentPosition(function(pos) {
    var lat = pos.coords.latitude, lng = pos.coords.longitude;
    if (addrInput) addrInput.value = 'https://maps.google.com/?q=' + lat + ',' + lng;
    toast('تم تحديد الموقع بنجاح ✅', 'success');
  }, function() {
    toast('تعذّر تحديد الموقع، يرجى إدخال العنوان يدوياً', 'warn');
    if (addrInput) addrInput.placeholder = 'العنوان أو رابط الموقع *';
  }, { enableHighAccuracy: true, timeout: 10000, maximumAge: 0 });
}

/* ============================================================
   FEED CACHE
   ============================================================ */
function getFeedCache() {
  try {
    var raw = localStorage.getItem(CONFIG.feedCacheKey);
    if (!raw) return null;
    var parsed = JSON.parse(raw);
    if (Date.now() - parsed.ts > CONFIG.feedCacheTTL) { localStorage.removeItem(CONFIG.feedCacheKey); return null; }
    return parsed.data;
  } catch(e) { return null; }
}
function setFeedCache(data) {
  try { localStorage.setItem(CONFIG.feedCacheKey, JSON.stringify({ ts: Date.now(), data: data })); } catch(e) {}
}

/* ============================================================
   HELPERS
   ============================================================ */
var imgCache = {};

function blogImg(url, size) {
  if (!url || typeof url !== 'string' || url.length < 8) return '';
  var key = url + '|' + size;
  if (imgCache[key] !== undefined) return imgCache[key];
  var result = url;
  try {
    if (url.indexOf('googleusercontent.com') >= 0) {
      // Format: ...=s1600 or .../filename=s1600
      var eqIdx = url.lastIndexOf('=');
      var slashIdx = url.lastIndexOf('/');
      if (eqIdx > slashIdx) {
        result = url.substring(0, eqIdx + 1) + size;
      } else {
        result = url + '=' + size;
      }
    } else if (url.indexOf('bp.blogspot.com') >= 0 || url.indexOf('blogspot.com') >= 0) {
      var replaced = url.replace(/\/[swh]\d+(-h\d+)?(-[a-zA-Z0-9]+)*\//g, '/' + size + '/');
      result = (replaced !== url) ? replaced : url.replace(/(\/[^\/]+\.(jpg|jpeg|png|webp|gif|avif))(\?.*)?$/i, '/' + size + '$1$3');
    }
  } catch(e) { result = url; }
  imgCache[key] = result;
  return result;
}

function toEnNum(str) { return String(str).replace(/[٠-٩]/g, function(w) { return '٠١٢٣٤٥٦٧٨٩'.indexOf(w); }); }
function parsePrice(str) { return parseFloat(toEnNum(str).replace(/[^\d.]/g,'')) || 0; }
function normalizeAr(s) {
  return (s||'').toLowerCase().replace(/[إأآا]/g,'ا').replace(/ى/g,'ي').replace(/ة/g,'ه').replace(/[ؤئء]/g,'ء').replace(/\s+/g,' ').trim();
}
function starsHTML(rating) {
  var key = Math.round(rating * 2);
  if (starsCache[key]) return starsCache[key];
  var s = '', full = Math.floor(rating), half = rating - full >= 0.5;
  for (var i = 1; i <= 5; i++) { s += (i <= full) ? '★' : (i === full+1 && half) ? '⯨' : '☆'; }
  starsCache[key] = s; return s;
}
function getVariantDiscount(v) {
  if (!v || !v.oldPrice || v.oldPrice <= v.price) return 0;
  return Math.round(((v.oldPrice - v.price) / v.oldPrice) * 100);
}
function formatPrice(n) { return (n || 0).toFixed(2); }
function priceHTML(amount, opts) {
  opts = opts || {};
  return '<span class="price-currency">' + CONFIG.currency + '</span><span class="price' + (opts.deal ? ' deal' : '') + '">' + formatPrice(amount) + '</span>';
}
function escapeHtml(s) {
  return String(s||'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}

/* ============================================================
   FETCH PRODUCTS FROM BLOGGER FEED
   ============================================================ */
function fetchProducts() {
  var cached = getFeedCache();
  if (cached) {
    products = cached;
    products.forEach(function(p) { productIndex[p.id] = p; allCategories.add(p.category); });
    initStore(); return;
  }
  fetch('/feeds/posts/default?alt=json&max-results=500')
    .then(function(res) { if (!res.ok) throw new Error('Feed HTTP ' + res.status); return res.json(); })
    .then(function(data) {
      if (!data.feed || !data.feed.entry) { initStore(); return; }
      var gid = 1;
      var FALLBACK_IMG = 'https://placehold.co/600x600/f5f5f5/aaaaaa?text=No+Image';
      var fallbackSet = { thumb: FALLBACK_IMG, medium: FALLBACK_IMG, full: FALLBACK_IMG };

      data.feed.entry.forEach(function(entry) {
        var postTitle = (entry.title && entry.title.$t || '').trim();
        var cats = ['عام'];
        if (entry.category && entry.category.length) {
          cats = entry.category.map(function(c) { return c.term; });
          cats.forEach(function(c) { allCategories.add(c); });
        } else { allCategories.add('عام'); }

        var rawHTML = (entry.content && entry.content.$t) || '';
        var sections = rawHTML.replace(/&nbsp;|​/gi,' ').split(/(?:\s*(?:<[^>]+>\s*)*\.{5,})/);

        var variants = [];
        var productRating = null, productRatingCount = null, publishedTs = 0;
        try { publishedTs = entry.published && entry.published.$t ? Date.parse(entry.published.$t) : 0; } catch(e) {}
        var isNew = publishedTs && (Date.now() - publishedTs) < 30*24*60*60*1000;

        sections.forEach(function(sec, sIdx) {
          var d = document.createElement('div');
          d.innerHTML = sec;

          /* ---- IMAGE EXTRACTION (fixed + deduplicated) ---- */
          var secImgs = [];
          var seenBases = {};
          d.querySelectorAll('img').forEach(function(el) {
            var raw = el.getAttribute('data-src')
                   || el.getAttribute('data-lazy-src')
                   || el.getAttribute('data-original')
                   || el.getAttribute('data-original-url')
                   || el.getAttribute('data-full-src')
                   || el.getAttribute('src')
                   || '';
            if (!raw || raw.length < 10) return;
            if (raw.startsWith('data:')) return;
            if (raw.indexOf('blank.gif') >= 0 || raw.indexOf('transparent.gif') >= 0) return;
            // Skip tiny Blogger thumbnails (=s1 to =s39)
            if (/=s([1-9]|[1-3]\d)$/.test(raw)) return;
            if (/\/s([1-9]|[1-3]\d)\//.test(raw)) return;

            // Normalize for deduplication
            var base = raw;
            if (raw.indexOf('googleusercontent.com') >= 0) base = raw.split('=')[0];
            else if (raw.indexOf('bp.blogspot.com') >= 0) base = raw.replace(/\/s\d+(-h\d+)?(-[a-zA-Z0-9]+)*\//g, '/');
            if (seenBases[base]) return;
            seenBases[base] = true;

            // Best full-size: from parent anchor
            var aPar = el.closest('a');
            var full = raw;
            if (aPar && aPar.href && /\.(jpg|jpeg|png|webp|gif|avif)/i.test(aPar.href)) full = aPar.href;

            secImgs.push({ thumb: blogImg(raw,'s600'), medium: blogImg(raw,'s800'), full: blogImg(full,'s1600') });
          });

          /* ---- TEXT / META EXTRACTION ---- */
          var cleanText = sec.replace(/<br\s*\/?>/gi,'\n').replace(/<\/p>|<\/div>|<\/h[1-6]>/gi,'\n').replace(/<[^>]+>/g,'');
          var lines = cleanText.split('\n').map(function(l) { return l.trim(); }).filter(function(l) { return l && !/^\.{3,}$/.test(l); });

          var vPrice = null, vOldPrice = null, vColor = null, vDesc = [];
          lines.forEach(function(line) {
            var pm = line.match(/^(?:السعر|سعر|Price)\s*[:\-.]?\s*(\d[\d.]*)/i);
            if (pm) { vPrice = parsePrice(pm[1]); return; }
            var om = line.match(/^(?:السعر القديم|سعر قديم|السعر قبل|Old Price)\s*[:\-.]?\s*(\d[\d.]*)/i);
            if (om) { vOldPrice = parsePrice(om[1]); return; }
            var rm = line.match(/^(?:التقييم|تقييم|Rating)\s*[:\-.]?\s*([\d.]+)/i);
            if (rm) { productRating = Math.max(0, Math.min(5, parseFloat(rm[1]))); return; }
            var cm = line.match(/^(?:عدد التقييمات|Reviews)\s*[:\-.]?\s*(\d+)/i);
            if (cm) { productRatingCount = parseInt(cm[1],10); return; }
            var clm = line.match(/^(?:اللون|النوع|الاسم|الخيار|Color|Type|Variant)\s*[:\-.]?\s*(.*)/i);
            if (clm) { vColor = clm[1].trim(); return; }
            vDesc.push(line);
          });
          if (!vColor) vColor = 'خيار ' + (sIdx + 1);

          if (secImgs.length > 0 || vPrice !== null || vDesc.length > 0) {
            variants.push({ color: vColor, price: vPrice, oldPrice: vOldPrice, desc: vDesc, images: secImgs.length ? secImgs : null, image: secImgs.length ? secImgs[0].thumb : null, imageMedium: secImgs.length ? secImgs[0].medium : null, imageFull: secImgs.length ? secImgs[0].full : null });
          }
        });

        if (variants.length > 0) {
          // Find best defaults from first variant that has data
          var basePrice = 0, baseOldPrice = null, baseDesc = [], baseImages = [fallbackSet];
          for (var vi = 0; vi < variants.length; vi++) { if (variants[vi].price !== null) { basePrice = variants[vi].price; break; } }
          for (var vi = 0; vi < variants.length; vi++) { if (variants[vi].oldPrice !== null) { baseOldPrice = variants[vi].oldPrice; break; } }
          for (var vi = 0; vi < variants.length; vi++) { if (variants[vi].desc && variants[vi].desc.length > 0) { baseDesc = variants[vi].desc; break; } }
          for (var vi = 0; vi < variants.length; vi++) { if (variants[vi].images && variants[vi].images.length > 0) { baseImages = variants[vi].images; break; } }

          variants.forEach(function(v) {
            if (v.price === null) v.price = basePrice;
            if (v.oldPrice === null) v.oldPrice = baseOldPrice;
            if (!v.desc || !v.desc.length) v.desc = baseDesc;
            if (!v.images || !v.images.length) { v.images = baseImages; v.image = baseImages[0].thumb; v.imageMedium = baseImages[0].medium; v.imageFull = baseImages[0].full; }
          });

          var first = variants[0];
          var p = {
            id: String(gid++),
            title: postTitle,
            price: first.price,
            oldPrice: first.oldPrice,
            category: cats[0],
            image: first.image || FALLBACK_IMG,
            imageMedium: first.imageMedium || FALLBACK_IMG,
            imageFull: first.imageFull || FALLBACK_IMG,
            images: first.images || [fallbackSet],
            variants: variants,
            desc: first.desc,
            rating: productRating,
            ratingCount: productRatingCount,
            publishedTs: publishedTs,
            isNew: isNew
          };
          products.push(p);
          productIndex[p.id] = p;
        }
      });
      setFeedCache(products);
      initStore();
    })
    .catch(function(e) { console.error('fetchProducts:', e); showFetchError(); initStore(); });
}

function showFetchError() {
  var grid = document.getElementById('products-grid');
  if (grid) grid.innerHTML = '<div class="empty-state"><div class="icon">⚠️</div><h3>تعذّر تحميل المنتجات</h3><p>تحقّق من اتصالك بالإنترنت ثم أعد المحاولة.</p></div>';
}

/* ============================================================
   INIT STORE
   ============================================================ */
function initStore() {
  var pre = document.getElementById('preloader');
  if (pre) { pre.style.opacity = '0'; setTimeout(function() { pre.style.display = 'none'; }, 350); }
  populateCategoryDropdown();
  renderSubNavCategories();
  applyAllFilters();
  updateCartUI();
  updateWishlistBadge();
  initZoom();
  updateGreeting();
  loadAddresses();       // ensure addresses loaded
  checkFirstVisit();     // show first-visit popup if needed
}
window.addEventListener('load', fetchProducts);

function updateGreeting() {
  var lbl = document.getElementById('greeting-lbl');
  if (!lbl) return;
  if (currentUser) lbl.textContent = 'مرحباً، ' + (currentUser.name || '').split(' ')[0];
}

/* ============================================================
   CATEGORIES
   ============================================================ */
function populateCategoryDropdown() {
  var sel = document.getElementById('search-cat');
  if (!sel) return;
  var cats = Array.from(allCategories).sort();
  sel.innerHTML = '<option value="">الكل</option>' + cats.map(function(c) { return '<option value="' + c + '">' + c + '</option>'; }).join('');
  sel.onchange = function() {
    var v = sel.value;
    currentCat = v || CONFIG.defaultCategory;
    document.querySelectorAll('.h-sub .sub-item').forEach(function(el) {
      el.classList.toggle('active', (el.dataset.cat === v) || (!v && el.dataset.cat === 'all'));
    });
    applyAllFilters();
  };
}

function categoryIcon(cat) {
  var p = products.find(function(pr) { return pr.category === cat && pr.image; });
  return p ? p.image : null;
}

var activeSubItemEl = null;
function renderSubNavCategories() {
  var subNav = document.getElementById('sub-nav');
  if (!subNav) return;
  var refNode = subNav.querySelector('.sub-item.deals');
  var cats = Array.from(allCategories).sort();
  cats.forEach(function(c) {
    var div = document.createElement('div');
    div.className = 'sub-item'; div.dataset.cat = c;
    var ic = document.createElement('span'); ic.className = 'sub-ic';
    var iconUrl = categoryIcon(c);
    if (iconUrl) {
      var im = document.createElement('img'); im.loading = 'lazy'; im.decoding = 'async'; im.src = iconUrl; im.alt = c;
      im.onerror = function() { this.remove(); ic.textContent = '🏷️'; };
      ic.appendChild(im);
    } else { ic.textContent = '🏷️'; }
    var lbl = document.createElement('span'); lbl.className = 'sub-lbl'; lbl.textContent = c;
    div.appendChild(ic); div.appendChild(lbl);
    div.onclick = function() { setCategory(c, div); };
    subNav.insertBefore(div, refNode);
  });
  activeSubItemEl = document.querySelector('.sub-item[data-cat="all"]');
}

function setCategory(cat, el) {
  if (activeSubItemEl) activeSubItemEl.classList.remove('active');
  if (el) { el.classList.add('active'); activeSubItemEl = el; }
  currentCat = cat;
  var sel = document.getElementById('search-cat');
  if (sel) sel.value = (cat === CONFIG.defaultCategory) ? '' : cat;
  applyAllFilters();
}

/* ============================================================
   SEARCH + SORT
   ============================================================ */
function handleSearch(q) {
  var bar = document.getElementById('search-results-bar');
  var trimmed = (q || '').trim();
  bar.classList.toggle('visible', !!trimmed);
  clearTimeout(searchDebounce);
  searchDebounce = setTimeout(function() { searchQuery = trimmed; applyAllFilters(); }, 250);
}
function triggerSearch() { var inp = document.getElementById('search-input'); handleSearch(inp ? inp.value : ''); }
function clearSearch() {
  searchQuery = ''; clearTimeout(searchDebounce);
  var inp = document.getElementById('search-input'); if (inp) inp.value = '';
  var bar = document.getElementById('search-results-bar'); if (bar) bar.classList.remove('visible');
  applyAllFilters();
}
function applySort() { sortMode = document.getElementById('sort-select').value; applyAllFilters(); }
function applySortFromShortcut(mode) { var sel = document.getElementById('sort-select'); if (sel) sel.value = mode; sortMode = mode; applyAllFilters(); }

/* ============================================================
   FILTER + SORT + RENDER
   ============================================================ */
function applyAllFilters() {
  var list = products;
  if (currentCat !== CONFIG.defaultCategory) list = list.filter(function(p) { return p.category === currentCat; });
  if (searchQuery) {
    var q = normalizeAr(searchQuery);
    list = list.filter(function(p) {
      return normalizeAr(p.title).indexOf(q) >= 0 || (p.desc||[]).some(function(d) { return normalizeAr(d).indexOf(q) >= 0; });
    });
    var rb = document.getElementById('search-results-text');
    if (rb) rb.innerHTML = '<b>' + list.length + '</b> نتيجة لـ "' + searchQuery + '"';
  }
  if (sortMode !== 'default') {
    list = list.slice();
    if (sortMode === 'price-asc')   list.sort(function(a,b) { return a.price - b.price; });
    else if (sortMode === 'price-desc') list.sort(function(a,b) { return b.price - a.price; });
    else if (sortMode === 'discount')   list.sort(function(a,b) { return getVariantDiscount(b.variants&&b.variants[0]||b) - getVariantDiscount(a.variants&&a.variants[0]||a); });
    else if (sortMode === 'rating')     list.sort(function(a,b) { return (b.rating||0) - (a.rating||0); });
    else if (sortMode === 'name')       list.sort(function(a,b) { return a.title.localeCompare(b.title,'ar'); });
  }
  requestAnimationFrame(function() { renderProducts(list); });
}

function renderProducts(list) {
  var grid  = document.getElementById('products-grid');
  var label = document.getElementById('product-count-label');
  if (label) label.textContent = list.length + ' منتج';

  if (!list.length) {
    grid.innerHTML = '<div class="empty-state"><div class="icon">🔍</div><h3>لا توجد منتجات</h3><p>' + (searchQuery ? 'لا توجد نتائج لـ "' + searchQuery + '"' : 'لا توجد منتجات في هذه الفئة') + '</p></div>';
    renderedIds = []; return;
  }

  var idSig    = list.map(function(p) { return p.id; }).join(',');
  var cacheSig = idSig + '|wlv=' + wishlistVersion;
  if (grid.dataset.lastSig === cacheSig) return;

  if (idSig === renderedIds.join(',') && grid.children.length) {
    list.forEach(function(p) {
      var btn = grid.querySelector('.wishlist-btn[data-pid="' + p.id + '"]');
      if (btn) { var a = wishlistSet.has(p.id); btn.classList.toggle('active',a); btn.textContent = a ? '❤️' : '🤍'; }
    });
    grid.dataset.lastSig = cacheSig; return;
  }

  renderedIds = list.map(function(p) { return p.id; });
  grid.dataset.lastSig = cacheSig;

  var html = '';
  for (var i = 0; i < list.length; i++) {
    var p = list[i];
    var firstV = (p.variants && p.variants.length) ? p.variants[0] : p;
    var d = getVariantDiscount(firstV);
    var isWl = wishlistSet.has(p.id);
    var img = (firstV.image || p.image || 'https://placehold.co/600x600/f5f5f5/aaaaaa?text=No+Image').replace(/"/g,'&quot;');
    var titleSafe = escapeHtml(p.title);
    var ratingBlock = '';
    if (p.rating != null) {
      ratingBlock = '<div class="product-rating"><span class="stars">' + starsHTML(p.rating) + '</span><span class="rating-count">' + (p.ratingCount != null ? '(' + p.ratingCount + ')' : '') + '</span></div>';
    } else { ratingBlock = '<div class="product-rating"></div>'; }
    var priceBlock = '<div class="price-row">' + priceHTML(firstV.price, { deal: !!firstV.oldPrice }) + '</div>';
    if (firstV.oldPrice) priceBlock += '<div class="old-price-row"><span class="old-price">' + formatPrice(firstV.oldPrice) + ' ' + CONFIG.currency + '</span></div>';

    html += '<div class="product-card" data-id="' + p.id + '">'
      + (d > 0 ? '<div class="disc-badge">خصم ' + d + '%</div>' : '')
      + (p.isNew ? '<div class="new-badge">جديد</div>' : '')
      + '<button class="wishlist-btn' + (isWl?' active':'') + '" data-pid="' + p.id + '" onclick="toggleWishlist(event,\'' + p.id + '\')" aria-label="المفضلة">' + (isWl?'❤️':'🤍') + '</button>'
      + '<div class="card-img-wrap" onclick="openDrawer(\'' + p.id + '\')">'
      + '<img loading="lazy" decoding="async" src="' + img + '" alt="' + titleSafe + '" onerror="this.src=\'https://placehold.co/600x600/f5f5f5/aaaaaa?text=Image+Error\'"/>'
      + '</div>'
      + '<h3 class="product-title" onclick="openDrawer(\'' + p.id + '\')">' + p.title + '</h3>'
      + ratingBlock
      + '<div class="card-foot"><div class="price-area">' + priceBlock + '</div>';
    var isMultiV = p.variants && p.variants.length > 1;
    if (isMultiV) {
      html += '<button class="btn-quickadd" onclick="openDrawer(\'' + p.id + '\')" aria-label="أضف للسلة">+</button>';
    } else {
      html += '<div class="cqw-wrap" id="cqw-' + p.id + '">'
        + '<button class="cqw-btn" onclick="cardQtyInc(event,\'' + p.id + '\')" aria-label="أضف للسلة">+</button>'
        + '<div class="cqw-pill">'
        + '<button class="cqw-inc" onclick="cardQtyInc(event,\'' + p.id + '\')" aria-label="زيادة">+</button>'
        + '<span class="cqw-val" id="cqwv-' + p.id + '"></span>'
        + '<button class="cqw-dec" onclick="cardQtyDec(event,\'' + p.id + '\')" aria-label="إنقاص">−</button>'
        + '</div></div>';
    }
    html += '</div></div>';
  }
  grid.innerHTML = html;
  refreshCardQtys();
}

function cardQtyInc(e, pid) {
  if (e) e.stopPropagation();
  var p = productIndex[pid]; if (!p) return;
  var cid = pid;
  var existing = cart.find(function(i) { return i.cid === cid; });
  if (existing) { existing.qty++; }
  else {
    var v = (p.variants && p.variants[0]) ? p.variants[0] : p;
    cart.push({ id: p.id, cid: cid, title: p.title, variant: '', price: v.price, image: v.image || p.image, imageFull: v.imageFull || p.imageFull, qty: 1 });
    toast('تمت الإضافة للسلة ✅', 'success');
  }
  saveCart(); updateCartUI(); updateCardQty(pid);
}

function cardQtyDec(e, pid) {
  if (e) e.stopPropagation();
  var cid = pid;
  var idx = cart.findIndex(function(i) { return i.cid === cid; });
  if (idx === -1) return;
  cart[idx].qty--;
  if (cart[idx].qty <= 0) cart.splice(idx, 1);
  saveCart(); updateCartUI(); updateCardQty(pid);
}

function updateCardQty(pid) {
  var wrap = document.getElementById('cqw-' + pid);
  var val  = document.getElementById('cqwv-' + pid);
  if (!wrap) return;
  var item = cart.find(function(i) { return i.cid === pid; });
  var qty  = item ? item.qty : 0;
  if (qty > 0) {
    wrap.classList.add('has-qty');
    if (val) val.textContent = qty;
  } else {
    wrap.classList.remove('has-qty');
    if (val) val.textContent = '';
  }
}

function refreshCardQtys() {
  var wraps = document.querySelectorAll('.cqw-wrap');
  for (var w = 0; w < wraps.length; w++) {
    updateCardQty(wraps[w].id.replace('cqw-', ''));
  }
}

function quickAdd(e, pid) { cardQtyInc(e, pid); }

/* ============================================================
   PRODUCT DRAWER
   ============================================================ */
function openDrawer(id) {
  if (drawerOpen) return;
  var p = productIndex[id]; if (!p) return;
  drawerOpen = true;
  currentDrawerProduct = p;
  var hasVariants = p.variants && p.variants.length > 0;
  var firstV = hasVariants ? p.variants[0] : p;
  currentDrawerSelected = hasVariants ? { color: firstV.color } : {};
  document.getElementById('drawer-title').textContent = 'تفاصيل المنتج';
  renderDrawerSlider(firstV.images || p.images);
  var d = getVariantDiscount(firstV);
  var savings = firstV.oldPrice ? (firstV.oldPrice - firstV.price).toFixed(2) : 0;
  var ratingLine = (p.rating != null)
    ? '<div class="rating-line"><span class="stars">' + starsHTML(p.rating) + '</span><span style="font-size:13px;color:var(--link)">' + p.rating + '</span>' + (p.ratingCount != null ? '<span style="font-size:13px;color:var(--link)">| ' + p.ratingCount + ' تقييم</span>' : '') + '</div>'
    : '<div class="rating-line" style="border-bottom:none;padding-bottom:0;margin-bottom:8px;color:var(--text-3);font-size:12px">منتج جديد</div>';
  var isFree = firstV.price >= CONFIG.freeShippingMin;
  document.getElementById('drawer-body').innerHTML =
    '<h2 class="drawer-title">' + escapeHtml(p.title) + '</h2>' + ratingLine
    + '<div class="drawer-price-box"><div class="drawer-price">' + priceHTML(firstV.price,{deal:!!firstV.oldPrice}) + '</div>'
    + '<div id="drawer-old-price-box">' + (firstV.oldPrice ? '<div class="drawer-old-price">' + (d ? '<span class="disc">-' + d + '%</span>' : '') + '<span class="lbl">السعر القائمة:</span><span class="old">' + formatPrice(firstV.oldPrice) + ' ' + CONFIG.currency + '</span></div>' + (d > 0 ? '<div class="drawer-savings">💰 توفّر ' + savings + ' ' + CONFIG.currency + '</div>' : '') : '') + '</div></div>'
    + buildOptionsHTML(p, firstV.color)
    + '<div class="delivery-block"><strong>التوصيل</strong>'
    + (isFree ? '<div><span class="free">شحن مجاني</span> للطلبات فوق ' + CONFIG.freeShippingMin + ' ' + CONFIG.currency + '</div>' : '<div>تكلفة الشحن: <b>' + CONFIG.shippingFee + ' ' + CONFIG.currency + '</b></div><div style="margin-top:4px;font-size:12px;color:var(--text-2)">أضف ' + (CONFIG.freeShippingMin - firstV.price).toFixed(2) + ' ' + CONFIG.currency + ' للحصول على شحن مجاني</div>')
    + '</div>'
    + '<div class="desc-section" id="drawer-desc-section"' + (firstV.desc && firstV.desc.length ? '' : ' style="display:none"') + '>'
    + '<div class="desc-heading">معلومات المنتج</div>'
    + '<div class="desc-content" id="drawer-desc-content">' + (firstV.desc ? firstV.desc.map(function(l) { return '<div>' + escapeHtml(l) + '</div>'; }).join('') : '') + '</div></div>';

  var wlBtn = document.getElementById('drawer-wl-btn');
  if (wlBtn) wlBtn.textContent = wishlistSet.has(p.id) ? '❤️' : '🤍';
  document.getElementById('drawer-add-btn').textContent = 'أضف إلى السلة';
  document.getElementById('drawer-add-btn').style.background = '';
  document.getElementById('drawer-add-btn').style.color = '';
  document.getElementById('drawer-add-btn').style.border = '';
  document.getElementById('drawer-buy-btn').style.opacity = '1';
  document.getElementById('drawer-add-btn').onclick = function() { addToCart(p.id, false); };
  document.getElementById('drawer-buy-btn').onclick = function() { addToCart(p.id, true); };
  var _initCid = (hasVariants && p.variants.length > 1) ? p.id + '-' + firstV.color : p.id;
  updateDrawerAddBtn(_initCid);
  openModal('product-modal');
}

function renderDrawerSlider(images) {
  if (!images || !images.length) return;
  var track = document.getElementById('drawer-track');
  var dots  = document.getElementById('drawer-dots');
  track.innerHTML = images.map(function(img, idx) {
    return '<img class="drawer-slide-img" loading="lazy" decoding="async" src="' + (img.medium||'') + '" onerror="this.src=\'https://placehold.co/800x800/f5f5f5/aaaaaa?text=Image+Not+Found\'" onclick="openZoom(\'' + (img.full||'').replace(/'/g,"\\'") + '\')" data-idx="' + idx + '"/>';
  }).join('');
  dots.innerHTML = images.length > 1 ? images.map(function(_,i) { return '<div class="dot' + (i===0?' active':'') + '" onclick="scrollToSlide(' + i + ')"></div>'; }).join('') : '';
  setTimeout(function() { if (track.firstElementChild) track.firstElementChild.scrollIntoView({ inline:'center', block:'nearest' }); }, 20);
  track.onscroll = function() {
    var w = track.offsetWidth || 1;
    var idx = Math.round(Math.abs(track.scrollLeft) / w);
    document.querySelectorAll('#drawer-dots .dot').forEach(function(d,i) { d.classList.toggle('active', i===idx); });
  };
}

function buildOptionsHTML(p, activeColor) {
  if (!p.variants || p.variants.length < 2) return '';
  return '<div class="option-group"><div class="option-label">الخيار: <span id="sel-color-text">' + escapeHtml(activeColor||'') + '</span></div><div class="pills" id="color-pills">'
    + p.variants.map(function(v) { return '<div class="pill ' + (v.color === activeColor ? 'active' : '') + '" onclick="selectColor(\'' + escapeHtml(p.id) + '\',\'' + v.color.replace(/'/g,"\\'") + '\',this)">' + escapeHtml(v.color) + '</div>'; }).join('')
    + '</div></div>';
}

function scrollToSlide(idx) {
  var track = document.getElementById('drawer-track');
  if (track && track.children[idx]) track.children[idx].scrollIntoView({ behavior:'smooth', inline:'center', block:'nearest' });
}

function selectColor(pid, color, el) {
  document.querySelectorAll('#color-pills .pill').forEach(function(e) { e.classList.remove('active'); });
  el.classList.add('active');
  var selText = document.getElementById('sel-color-text'); if (selText) selText.textContent = color;
  var p = productIndex[pid]; if (!p) return;
  var variant = p.variants.find(function(v) { return v.color === color; }); if (!variant) return;
  currentDrawerSelected = { color: variant.color };
  var dp = document.querySelector('.drawer-price'); if (dp) dp.innerHTML = priceHTML(variant.price,{deal:!!variant.oldPrice});
  var dv = getVariantDiscount(variant);
  var sv = variant.oldPrice ? (variant.oldPrice - variant.price).toFixed(2) : 0;
  var ob = document.getElementById('drawer-old-price-box');
  if (ob) ob.innerHTML = variant.oldPrice ? '<div class="drawer-old-price">' + (dv ? '<span class="disc">-' + dv + '%</span>' : '') + '<span class="lbl">السعر القائمة:</span><span class="old">' + formatPrice(variant.oldPrice) + ' ' + CONFIG.currency + '</span></div>' + (dv > 0 ? '<div class="drawer-savings">💰 توفّر ' + sv + ' ' + CONFIG.currency + '</div>' : '') : '';
  if (variant.images && variant.images.length) renderDrawerSlider(variant.images);
  var ds = document.getElementById('drawer-desc-section'); var dc = document.getElementById('drawer-desc-content');
  if (variant.desc && variant.desc.length) {
    if (ds) ds.style.display = 'block';
    if (dc) dc.innerHTML = variant.desc.map(function(l) { return '<div>' + escapeHtml(l) + '</div>'; }).join('');
  } else { if (ds) ds.style.display = 'none'; }
  var updCid = pid + (color ? '-' + color : '');
  updateDrawerAddBtn(updCid);
}

function drawerToggleWishlist() {
  if (!currentDrawerProduct) return;
  toggleWishlist(null, currentDrawerProduct.id);
  var wb = document.getElementById('drawer-wl-btn'); if (wb) wb.textContent = wishlistSet.has(currentDrawerProduct.id) ? '❤️' : '🤍';
}

/* ============================================================
   CART
   ============================================================ */
function addToCart(pid, buyNow) {
  var p = productIndex[pid]; if (!p) return;
  var finalPrice = p.price, varLabel = '', varImage = p.image, varImageFull = p.imageFull;
  if (p.variants && p.variants.length > 1) {
    if (!currentDrawerSelected.color) { toast('يرجى اختيار الخيار أولاً 🎨','warn'); return; }
    var v = p.variants.find(function(vt) { return vt.color === currentDrawerSelected.color; });
    if (v) { finalPrice = v.price; varLabel = v.color; varImage = v.image || p.image; varImageFull = v.imageFull || p.imageFull; }
  } else if (p.variants && p.variants.length === 1) {
    finalPrice = p.variants[0].price; varImage = p.variants[0].image || p.image; varImageFull = p.variants[0].imageFull || p.imageFull;
  }
  var cid = p.id + (varLabel ? '-' + varLabel : '');
  var existing = cart.find(function(i) { return i.cid === cid; });
  if (existing) existing.qty++;
  else cart.push({ id: p.id, cid: cid, title: p.title, variant: varLabel, price: finalPrice, image: varImage, imageFull: varImageFull, qty: 1 });
  saveCart(); updateCartUI();
  updateDrawerAddBtn(cid);
  toast('تمت الإضافة للسلة ✅', 'success');
  if (buyNow) { closeModal('product-modal'); setTimeout(function() { openModal('cart-modal'); }, 360); }
}

function updateDrawerAddBtn(cid) {
  var btn = document.getElementById('drawer-add-btn');
  if (!btn) return;
  var item = cart.find(function(i) { return i.cid === cid; });
  if (item) {
    btn.textContent = '✓ في السلة (' + item.qty + ')';
    btn.style.background = 'var(--success)';
    btn.style.color = '#fff';
    btn.style.border = '1px solid var(--success)';
  } else {
    btn.textContent = 'أضف إلى السلة';
    btn.style.background = '';
    btn.style.color = '';
    btn.style.border = '';
  }
}

function removeFromCart(cid) { cart = cart.filter(function(i) { return i.cid !== cid; }); saveCart(); updateCartUI(); }

function changeQty(cid, delta) {
  var item = cart.find(function(i) { return i.cid === cid; }); if (!item) return;
  item.qty = Math.max(1, item.qty + delta);
  saveCart(); updateCartItemRow(cid, item); updateCartTotals(); updateCartBadge(); updateStickyBar(); updateSheetTotals(); refreshCardQtys();
}

function qtyCtrlHTML(item) {
  var decAction = item.qty === 1 ? 'removeFromCart(\'' + item.cid + '\')' : 'changeQty(\'' + item.cid + '\',-1)';
  var decBtn = '<button class="qty-btn" onclick="' + decAction + '" aria-label="إنقاص">−</button>';
  return decBtn + '<span class="qty-val" data-cid="' + item.cid + '">' + item.qty + '</span><button class="qty-btn" onclick="changeQty(\'' + item.cid + '\',1)" aria-label="زيادة">+</button>';
}

function updateCartItemRow(cid, item) {
  var ctrls = document.querySelectorAll('.cart-qty-ctrl[data-cid="' + cid + '"]');
  var pEls  = document.querySelectorAll('.cart-item-price[data-cid="' + cid + '"]');
  var lineTxt = (item.price * item.qty).toFixed(2) + ' ' + CONFIG.currency;
  for (var c = 0; c < ctrls.length; c++) ctrls[c].innerHTML = qtyCtrlHTML(item);
  for (var e = 0; e < pEls.length; e++)  pEls[e].textContent = lineTxt;
}

function updateSheetTotals() {
  var sheet = document.getElementById('cart-sheet');
  if (!sheet || !sheet.classList.contains('show')) return;
  var foot = document.getElementById('cs-footer');
  if (!foot) return;
  var subtotal = cart.reduce(function(s,i) { return s + i.price * i.qty; }, 0);
  var shipping = subtotal >= CONFIG.freeShippingMin ? 0 : CONFIG.shippingFee;
  var total    = subtotal + shipping;
  var need     = CONFIG.freeShippingMin - subtotal;
  var valEl = foot.querySelector('.cs-total-val');
  if (valEl) valEl.textContent = total.toFixed(2) + ' ' + CONFIG.currency;
  var note = foot.querySelector('.cs-ship-note');
  if (note) {
    if (shipping === 0) { note.className = 'cs-ship-note'; note.innerHTML = '🚚 مؤهّل للشحن المجاني!'; }
    else { note.className = 'cs-ship-note needs-more'; note.innerHTML = 'أضف <b>' + need.toFixed(2) + ' ' + CONFIG.currency + '</b> للحصول على شحن مجاني'; }
  }
}

function cartRecommendationsHTML() {
  if (!products || !products.length) return '';
  var inCart = {};
  cart.forEach(function(i) { inCart[i.id] = true; });
  var pool = products.filter(function(p) { return !inCart[p.id]; });
  if (!pool.length) return '';
  var picks = pool.slice(0, 12);
  var cards = picks.map(function(p) {
    var v   = (p.variants && p.variants[0]) ? p.variants[0] : p;
    var img = (v.image || p.image || 'https://placehold.co/300x300/f5f5f5/aaaaaa?text=No+Image').replace(/"/g,'&quot;');
    var isMultiV = p.variants && p.variants.length > 1;
    var addBtn = isMultiV
      ? '<button class="reco-add" onclick="openDrawer(\'' + p.id + '\')">اختر الخيار</button>'
      : '<button class="reco-add" onclick="recoAdd(\'' + p.id + '\')">+ أضف للسلة</button>';
    return '<div class="reco-card">'
      + '<img loading="lazy" decoding="async" src="' + img + '" onclick="openDrawer(\'' + p.id + '\')" onerror="this.src=\'https://placehold.co/300x300/f5f5f5/aaaaaa?text=Image+Error\'" alt="' + escapeHtml(p.title) + '"/>'
      + '<div class="reco-title" onclick="openDrawer(\'' + p.id + '\')">' + escapeHtml(p.title) + '</div>'
      + '<div class="reco-price">' + formatPrice(v.price) + ' ' + CONFIG.currency + '</div>'
      + addBtn + '</div>';
  }).join('');
  return '<div class="cart-reco"><div class="cart-reco-head">✨ قد يعجبك أيضاً</div><div class="cart-reco-scroll">' + cards + '</div></div>';
}

function recoAdd(pid) { cardQtyInc(null, pid); }

function updateCartBadge() {
  var total = cart.reduce(function(s,i) { return s + i.qty; }, 0);
  var b = document.getElementById('cart-badge'); if (b) b.textContent = total;
}

function updateStickyBar() {
  var subtotal = cart.reduce(function(s,i) { return s + i.price * i.qty; }, 0);
  var count    = cart.reduce(function(s,i) { return s + i.qty; }, 0);
  var bar   = document.getElementById('sticky-bar');
  var val   = document.getElementById('sticky-total-val');
  var cnt   = document.getElementById('sticky-count');
  var thumb = document.getElementById('sticky-thumb');
  var promo = document.getElementById('promo-text');
  if (bar)   bar.classList.toggle('show', cart.length > 0);
  if (val)   val.textContent  = subtotal.toFixed(2) + ' ' + CONFIG.currency;
  if (cnt)   cnt.textContent  = count + ' ' + (count === 1 ? 'سلعة' : 'سلع');
  if (thumb) { var last = cart[cart.length - 1]; if (last && last.image) { thumb.src = last.image; thumb.style.visibility = 'visible'; } }
  if (promo) {
    if (subtotal >= CONFIG.freeShippingMin) promo.innerHTML = '🎉 تهانينا! طلبك مؤهّل للشحن المجاني';
    else promo.innerHTML = 'أضف سلعاً بقيمة <b>' + (CONFIG.freeShippingMin - subtotal).toFixed(2) + ' ' + CONFIG.currency + '</b> أو أكثر للحصول على <b>شحن مجاني</b>';
  }
}

function updateCartTotals() {
  var sub  = cart.reduce(function(s,i) { return s + i.price * i.qty; }, 0);
  var ship = sub >= CONFIG.freeShippingMin ? 0 : CONFIG.shippingFee;
  var tot  = sub + ship;
  var se = document.querySelector('#cart-summary .summary-row[data-row="sub"] span:last-child');
  var he = document.querySelector('#cart-summary .summary-row[data-row="ship"] span:last-child');
  var te = document.querySelector('#cart-summary .summary-total span:last-child');
  if (se) se.textContent = sub.toFixed(2) + ' ' + CONFIG.currency;
  if (he) he.innerHTML   = ship === 0 ? '<span class="free-tag">مجاني</span>' : ship.toFixed(2) + ' ' + CONFIG.currency;
  if (te) te.textContent = tot.toFixed(2) + ' ' + CONFIG.currency;
}

function toggleCartSheet() {
  var sheet = document.getElementById('cart-sheet');
  if (sheet && (sheet.classList.contains('show') || sheet.classList.contains('animating'))) closeCartSheet();
  else openCartSheet();
}

function openCartSheet() {
  if (!cart.length) return;
  var sheet = document.getElementById('cart-sheet');
  if (!sheet) return;
  if (sheet.classList.contains('show')) return;
  var pages = document.getElementById('cs-pages');
  if (pages) pages.classList.remove('on-step2');
  renderCartSheet();
  sheet.classList.add('animating');
  sheet.style.display = 'flex';
  document.getElementById('sticky-bar').classList.add('sheet-open');
  document.body.style.overflow = 'hidden';
  requestAnimationFrame(function() {
    requestAnimationFrame(function() { sheet.classList.add('show'); sheet.classList.remove('animating'); });
  });
}

function closeCartSheet() {
  var sheet = document.getElementById('cart-sheet');
  if (!sheet) return;
  sheet.classList.remove('show'); sheet.classList.remove('animating');
  var bar = document.getElementById('sticky-bar');
  if (bar) bar.classList.remove('sheet-open');
  var pages = document.getElementById('cs-pages');
  if (pages) pages.classList.remove('on-step2');
  document.body.style.overflow = '';
  setTimeout(function() { if (!sheet.classList.contains('show')) sheet.style.display = 'none'; }, 340);
}

function sheetBackdropClose(e) {
  if (e.target === document.getElementById('cart-sheet')) closeCartSheet();
}

function renderCartSheet() {
  var body   = document.getElementById('cs-body');
  var footer = document.getElementById('cs-footer');
  if (!body || !footer) return;
  if (!cart.length) { closeCartSheet(); return; }

  body.innerHTML = cart.map(function(item) {
    var vTag = (item.variant && item.variant.trim())
      ? '<span style="display:inline-block;background:#e8f4ff;color:var(--amazon-blue);font-size:11px;font-weight:700;padding:2px 9px;border-radius:20px;margin:2px 0 4px;">' + escapeHtml(item.variant) + '</span>'
      : '';
    return '<div class="cart-item">'
      + '<img class="cart-item-img" src="' + escapeHtml(item.image||'') + '" onclick="openZoom(\'' + escapeHtml(item.imageFull||item.image||'').replace(/'/g,"\\'") + '\')" onerror="this.src=\'https://placehold.co/90x90/f5f5f5/aaaaaa?text=Image+Error\'" alt="' + escapeHtml(item.title) + '"/>'
      + '<div class="cart-item-info"><div class="cart-item-title">' + escapeHtml(item.title) + '</div>'
      + vTag
      + '<div class="cart-item-stock">&#10003; متوفّر في المخزون</div>'
      + '<div class="cart-item-unit">' + formatPrice(item.price) + ' ' + CONFIG.currency + ' / للقطعة</div>'
      + '<div class="cart-item-bottom">'
      + '<div class="cart-qty-ctrl" data-cid="' + item.cid + '">' + qtyCtrlHTML(item) + '</div>'
      + '<span class="cart-item-price" data-cid="' + item.cid + '">' + (item.price*item.qty).toFixed(2) + ' ' + CONFIG.currency + '</span>'
      + '</div></div></div>';
  }).join('') + cartRecommendationsHTML();

  var subtotal = cart.reduce(function(s,i) { return s + i.price * i.qty; }, 0);
  var shipping = subtotal >= CONFIG.freeShippingMin ? 0 : CONFIG.shippingFee;
  var total    = subtotal + shipping;
  var need     = CONFIG.freeShippingMin - subtotal;
  var shipNote = shipping === 0
    ? '<div class="cs-ship-note">&#128666; مؤهّل للشحن المجاني!</div>'
    : '<div class="cs-ship-note needs-more">أضف <b>' + need.toFixed(2) + ' ' + CONFIG.currency + '</b> للحصول على شحن مجاني</div>';

  footer.innerHTML = shipNote
    + '<div class="cs-totals"><span class="cs-total-label">الإجمالي شامل الشحن</span><span class="cs-total-val">' + total.toFixed(2) + ' ' + CONFIG.currency + '</span></div>'
    + '<button class="btn-cs-checkout" onclick="goToCartStep2()">متابعة &#10145;</button>';
}

function goToCartStep2() {
  var pages = document.getElementById('cs-pages');
  if (!pages) return;
  renderCheckoutStep();
  pages.classList.add('on-step2');
}

function goToCartStep1() {
  var pages = document.getElementById('cs-pages');
  if (pages) pages.classList.remove('on-step2');
}

function renderCheckoutStep() {
  var body = document.getElementById('cs-checkout-body');
  var foot = document.getElementById('cs-checkout-footer');
  if (!body || !foot) return;
  var subtotal = cart.reduce(function(s,i){return s+i.price*i.qty;},0);
  var shipping = subtotal >= CONFIG.freeShippingMin ? 0 : CONFIG.shippingFee;
  var total    = subtotal + shipping;
  var itemsList = cart.map(function(item, n) {
    var label = escapeHtml(item.title);
    if (item.variant && item.variant.trim()) label += ' – ' + escapeHtml(item.variant);
    return '<div class="cs-order-item">'
      + '<span>' + (n+1) + '. ' + label + ' ×' + item.qty + '</span>'
      + '<span>' + (item.price*item.qty).toFixed(2) + ' ' + CONFIG.currency + '</span>'
      + '</div>';
  }).join('');
  var shipRow = shipping === 0
    ? '<div class="cs-order-item"><span>&#128666; الشحن</span><span style="color:var(--success);font-weight:800;">مجاني</span></div>'
    : '<div class="cs-order-item"><span>الشحن</span><span>' + shipping.toFixed(2) + ' ' + CONFIG.currency + '</span></div>';
  body.innerHTML = '<div class="cs-order-summary">'
    + '<div class="cs-order-summary-title">&#128203; ملخص الطلب</div>'
    + itemsList + shipRow
    + '<div class="cs-order-total-row"><span>الإجمالي</span><span>' + total.toFixed(2) + ' ' + CONFIG.currency + '</span></div>'
    + '</div>'
    + '<h4 style="font-size:14px;font-weight:800;color:var(--text);margin:0 0 10px;">&#128204; بيانات التوصيل والدفع</h4>'
    + (!currentUser ? '<div id="cs-google-auth"></div><div class="guest-divider">&#10097; أو أكمل كزائر</div>' : renderUserCard())
    + '<div class="form-row"><input class="pro-input" id="cs-c-name" placeholder="الاسم الكامل *" style="margin:0" required/>'
    + '<input class="pro-input" id="cs-c-phone" placeholder="رقم الجوال *" type="tel" inputmode="tel" style="margin:0" required/></div>'
    + '<div class="loc-wrap"><input class="pro-input" id="cs-c-addr" placeholder="العنوان أو رابط الموقع *" required/>'
    + '<button class="btn-location" type="button" onclick="getLocation()" title="&#128205;">&#128205;</button></div>'
    + '<select class="pro-input" id="cs-c-pay" required>'
    + '<option value="" disabled selected>اختر وسيلة الدفع *</option>'
    + '<option value="الدفع عند الاستلام">الدفع عند الاستلام</option>'
    + '<option value="تحويل بنكي">تحويل بنكي</option>'
    + '</select>'
    + '<textarea class="pro-input" id="cs-c-notes" placeholder="ملاحظات (اختياري)" rows="2"></textarea>';
  foot.innerHTML = '<button class="btn-cs-whatsapp" id="cs-btn-confirm" onclick="submitOrderFromSheet()">&#128172; إرسال الطلب عبر واتساب</button>';
  setTimeout(function() { renderGoogleButtonSheet(); prefillCheckoutStep(); }, 50);
}

function goToCheckout() { goToCartStep2(); }

function renderGoogleButtonSheet() {
  var container = document.getElementById('cs-google-auth');
  if (!container) return;
  if (currentUser) { container.innerHTML = ''; return; }
  if (window.google && google.accounts && google.accounts.id) {
    try {
      google.accounts.id.initialize({ client_id: '360615303745-h45ri50dd4mlfarff2rbu2tivmho822u.apps.googleusercontent.com', callback: handleCredentialResponse });
      google.accounts.id.renderButton(container, { theme:'outline', size:'large', shape:'pill', width:250 });
    } catch(e) { container.innerHTML = '<span style="font-size:12px;color:var(--text-3)">تعذّر تحميل تسجيل الدخول</span>'; }
  } else { container.innerHTML = '<span style="font-size:12px;color:var(--text-3)">جاري تحميل تسجيل الدخول…</span>'; }
}

function prefillCheckoutStep() {
  if (currentUser) { var ni = document.getElementById('cs-c-name'); if (ni && !ni.value) ni.value = currentUser.name || ''; }
  var addrSrc = checkoutPrefillAddr;
  if (!addrSrc && savedAddresses.length > 0 && savedAddresses[selectedAddressIndex]) addrSrc = savedAddresses[selectedAddressIndex];
  if (addrSrc) {
    var n2 = document.getElementById('cs-c-name');  if (n2 && !n2.value && addrSrc.name)      n2.value = addrSrc.name;
    var ph = document.getElementById('cs-c-phone'); if (ph && !ph.value && addrSrc.phone)     ph.value = addrSrc.phone;
    var ad = document.getElementById('cs-c-addr');  if (ad && !ad.value && addrSrc.formatted) ad.value = addrSrc.formatted;
  }
}

function submitOrderFromSheet() {
  var name  = ((document.getElementById('cs-c-name')  || {}).value || '').trim();
  var phone = ((document.getElementById('cs-c-phone') || {}).value || '').trim();
  var addr  = ((document.getElementById('cs-c-addr')  || {}).value || '').trim();
  var pay   = ((document.getElementById('cs-c-pay')   || {}).value || '');
  var notes = ((document.getElementById('cs-c-notes') || {}).value || '').trim();

  if (!name)  return toast('يرجى إدخال الاسم الكامل', 'warn');
  if (!phone) return toast('يرجى إدخال رقم الجوال', 'warn');
  if (!addr)  return toast('يرجى إدخال العنوان أو مشاركة الموقع', 'warn');
  if (!pay)   return toast('يرجى اختيار وسيلة الدفع', 'warn');

  var btn = document.getElementById('cs-btn-confirm');
  var orig = btn ? btn.innerHTML : '';
  if (btn) { btn.innerHTML = 'جاري المعالجة... ⏳'; btn.disabled = true; btn.style.opacity = '0.7'; }

  setTimeout(function() {
    var subtotal = cart.reduce(function(s,i) { return s + i.price * i.qty; }, 0);
    var shipping = subtotal >= CONFIG.freeShippingMin ? 0 : CONFIG.shippingFee;
    var total    = subtotal + shipping;
    var emailStr = currentUser ? '\n✉️ *الإيميل:* ' + currentUser.email : '';

    var lines = cart.map(function(i, n) {
      var line = (n + 1) + '. *' + i.title + '*';
      if (i.variant && i.variant.trim()) line += ' — ' + i.variant;
      line += '\n   الكمية: ' + i.qty + ' × ' + i.price.toFixed(2) + ' ' + CONFIG.currency;
      line += '\n   المجموع: *' + (i.price * i.qty).toFixed(2) + ' ' + CONFIG.currency + '*';
      return line;
    }).join('\n\n');

    var msg = '🛒 *طلب جديد من ' + CONFIG.storeName + '*\n\n'
      + '👤 *الاسم:* ' + name + '\n'
      + '📞 *الجوال:* ' + phone + emailStr + '\n'
      + '📍 *العنوان/الموقع:* ' + addr + '\n'
      + '💳 *الدفع:* ' + pay + '\n\n'
      + '*المنتجات:*\n' + lines + '\n\n'
      + '📦 *الشحن:* ' + (shipping === 0 ? 'مجاني' : shipping.toFixed(2) + ' ' + CONFIG.currency) + '\n'
      + '💰 *الإجمالي النهائي: ' + total.toFixed(2) + ' ' + CONFIG.currency + '*'
      + (notes ? '\n\n📝 *ملاحظات:* ' + notes : '');

    var order = { id: 'ORD-' + Date.now(), date: new Date().toLocaleDateString('ar-SA'), items: cart.slice(), total: total, status: 'جديد', name: name, phone: phone, addr: addr, pay: pay };
    orderHistory.unshift(order); if (orderHistory.length > 20) orderHistory.pop(); saveHistory();

    window.open('https://wa.me/' + CONFIG.whatsapp + '?text=' + encodeURIComponent(msg), '_blank');
    cart = []; saveCart();
    checkoutFormVisible = false; checkoutPrefillAddr = null;
    closeCartSheet(); closeModal('cart-modal'); updateCartUI();
    toast('تم تحويلك للواتساب لإرسال الطلب! ✅', 'success');
    if (btn) { btn.innerHTML = orig; btn.disabled = false; btn.style.opacity = '1'; }
  }, 800);
}

function updateCartUI() {
  updateCartBadge(); updateStickyBar(); refreshCardQtys();
  var sheet = document.getElementById('cart-sheet');
  if (sheet && sheet.classList.contains('show')) {
    var _pages = document.getElementById('cs-pages');
    if (!_pages || !_pages.classList.contains('on-step2')) renderCartSheet();
  }
  var modal = document.getElementById('cart-modal');
  if (modal && modal.classList.contains('show')) renderCartBody(cart.reduce(function(s,i) { return s + i.price*i.qty; }, 0));
}

function renderCartBody(subtotal) {
  var body    = document.getElementById('cart-body');
  var summary = document.getElementById('cart-summary');
  if (!body || !summary) return;

  if (!cart.length) {
    body.innerHTML    = '<div class="cart-empty"><div class="icon">🛒</div><h3 style="font-size:18px;color:var(--text);margin:0 0 6px">سلتك فارغة</h3><p>أضف بعض المنتجات للمتابعة</p></div>';
    summary.innerHTML = ''; return;
  }

  body.innerHTML = cart.map(function(item) {
    var vTag = (item.variant && item.variant.trim())
      ? '<span style="display:inline-block;background:#e8f4ff;color:var(--amazon-blue);font-size:11px;font-weight:700;padding:2px 9px;border-radius:20px;margin:2px 0 4px;">' + escapeHtml(item.variant) + '</span>'
      : '';
    return '<div class="cart-item">'
      + '<img class="cart-item-img" src="' + escapeHtml(item.image||'') + '" onclick="openZoom(\'' + escapeHtml(item.imageFull||item.image||'').replace(/'/g,"\\'") + '\')" onerror="this.src=\'https://placehold.co/90x90/f5f5f5/aaaaaa?text=Image+Error\'" alt="' + escapeHtml(item.title) + '"/>'
      + '<div class="cart-item-info"><div class="cart-item-title">' + escapeHtml(item.title) + '</div>'
      + vTag
      + '<div class="cart-item-stock">✓ متوفّر في المخزون</div>'
      + '<div class="cart-item-unit">' + formatPrice(item.price) + ' ' + CONFIG.currency + ' / للقطعة</div>'
      + '<div class="cart-item-bottom">'
      + '<div class="cart-qty-ctrl" data-cid="' + item.cid + '">' + qtyCtrlHTML(item) + '</div>'
      + '<span class="cart-item-price" data-cid="' + item.cid + '">' + (item.price*item.qty).toFixed(2) + ' ' + CONFIG.currency + '</span>'
      + '</div></div></div>';
  }).join('') + cartRecommendationsHTML();

  var shipping = subtotal >= CONFIG.freeShippingMin ? 0 : CONFIG.shippingFee;
  var total    = subtotal + shipping;
  var need     = CONFIG.freeShippingMin - subtotal;

  // Determine if we have a selected address to preview
  var addrPreviewHtml = '';
  if (savedAddresses.length > 0 && savedAddresses[selectedAddressIndex]) {
    var sa = savedAddresses[selectedAddressIndex];
    var saFormatted = sa.formatted || [sa.street, sa.district, sa.city].filter(Boolean).join('، ');
    addrPreviewHtml = '<div class="selected-addr-preview"><span class="pin">📍</span>'
      + '<div><div>' + escapeHtml(sa.name || saFormatted) + '</div><div style="font-size:12px;color:var(--text-2)">' + escapeHtml(saFormatted) + '</div>'
      + '<button class="change-addr" onclick="showCheckoutFlow()">تغيير العنوان</button></div></div>';
  }

  summary.innerHTML =
    '<div class="summary-row" data-row="sub"><span>المجموع الفرعي (' + cart.reduce(function(s,i){return s+i.qty;},0) + ' منتج)</span><span>' + subtotal.toFixed(2) + ' ' + CONFIG.currency + '</span></div>'
    + '<div class="summary-row" data-row="ship"><span>الشحن</span><span>' + (shipping===0 ? '<span class="free-tag">مجاني</span>' : shipping.toFixed(2)+' '+CONFIG.currency) + '</span></div>'
    + (shipping > 0 ? '<div class="shipping-progress">أضف <b>' + need.toFixed(2) + ' ' + CONFIG.currency + '</b> للحصول على شحن مجاني</div>' : '')
    + '<div class="summary-row summary-total"><span>الإجمالي</span><span>' + total.toFixed(2) + ' ' + CONFIG.currency + '</span></div>'
    + (currentUser ? renderUserCard() : '')
    + addrPreviewHtml
    + (!checkoutFormVisible ? '<button class="btn-checkout" id="checkout-btn" onclick="showCheckoutFlow()">المتابعة للدفع</button>' : '')
    + '<div class="' + (checkoutFormVisible ? 'checkout-form show' : 'checkout-form') + '" id="checkout-form">'
    + '<h4>بيانات التوصيل والدفع</h4>'
    + (!currentUser ? '<div id="google-auth-container"></div><div class="guest-divider">أو أكمل كزائر</div>' : '')
    + '<div class="form-row">'
    + '<input class="pro-input" id="c-name" placeholder="الاسم الكامل *" style="margin:0" required/>'
    + '<input class="pro-input" id="c-phone" placeholder="رقم الجوال *" type="tel" inputmode="tel" style="margin:0" required/>'
    + '</div>'
    + '<div class="loc-wrap"><input class="pro-input" id="c-addr" placeholder="العنوان أو رابط الموقع *" required/>'
    + '<button class="btn-location" type="button" onclick="getLocation()" title="مشاركة موقعي الحالي">📍</button></div>'
    + '<select class="pro-input" id="c-pay" required>'
    + '<option value="" disabled selected>اختر وسيلة الدفع *</option>'
    + '<option value="الدفع عند الاستلام">الدفع عند الاستلام</option>'
    + '<option value="تحويل بنكي">تحويل بنكي</option>'
    + '</select>'
    + '<textarea class="pro-input" id="c-notes" placeholder="ملاحظات (اختياري)" rows="2"></textarea>'
    + '<button class="btn-confirm" id="btn-confirm-order" onclick="submitOrder()">إرسال الطلب عبر واتساب 💬</button>'
    + '</div>';

  setTimeout(function() { renderGoogleButton(); prefillCheckoutForm(); }, 50);
}

function renderUserCard() {
  if (!currentUser) return '';
  return '<div class="user-card"><img src="' + escapeHtml(currentUser.picture||'') + '" onerror="this.style.display=\'none\'"/><span>مرحباً، <b>' + escapeHtml(currentUser.name||'') + '</b></span><button class="logout-link" onclick="logoutGoogle()">خروج</button></div>';
}

function prefillCheckoutForm() {
  if (currentUser) { var ni = document.getElementById('c-name'); if (ni && !ni.value) ni.value = currentUser.name || ''; }
  // Pre-fill from explicitly selected address (from address picker)
  var addrSrc = checkoutPrefillAddr;
  // Fall back to default saved address
  if (!addrSrc && savedAddresses.length > 0 && savedAddresses[selectedAddressIndex]) {
    addrSrc = savedAddresses[selectedAddressIndex];
  }
  if (addrSrc) {
    var ni2 = document.getElementById('c-name');  if (ni2 && !ni2.value && addrSrc.name)      ni2.value = addrSrc.name;
    var pi  = document.getElementById('c-phone'); if (pi  && !pi.value  && addrSrc.phone)     pi.value  = addrSrc.phone;
    var ai  = document.getElementById('c-addr');  if (ai  && !ai.value  && addrSrc.formatted) ai.value  = addrSrc.formatted;
  }
}

/* ============================================================
   SUBMIT ORDER → WHATSAPP
   ============================================================ */
function submitOrder() {
  var name  = ((document.getElementById('c-name')  || {}).value || '').trim();
  var phone = ((document.getElementById('c-phone') || {}).value || '').trim();
  var addr  = ((document.getElementById('c-addr')  || {}).value || '').trim();
  var pay   = ((document.getElementById('c-pay')   || {}).value || '');
  var notes = ((document.getElementById('c-notes') || {}).value || '').trim();

  if (!name)  return toast('يرجى إدخال الاسم الكامل', 'warn');
  if (!phone) return toast('يرجى إدخال رقم الجوال', 'warn');
  if (!addr)  return toast('يرجى إدخال العنوان أو مشاركة الموقع', 'warn');
  if (!pay)   return toast('يرجى اختيار وسيلة الدفع', 'warn');

  var btn = document.getElementById('btn-confirm-order');
  var orig = btn ? btn.innerHTML : '';
  if (btn) { btn.innerHTML = 'جاري المعالجة... ⏳'; btn.disabled = true; btn.style.opacity = '0.7'; }

  setTimeout(function() {
    var subtotal = cart.reduce(function(s,i) { return s + i.price * i.qty; }, 0);
    var shipping = subtotal >= CONFIG.freeShippingMin ? 0 : CONFIG.shippingFee;
    var total    = subtotal + shipping;
    var emailStr = currentUser ? '\n✉️ *الإيميل:* ' + currentUser.email : '';

    var lines = cart.map(function(i, n) {
      var line = (n + 1) + '. *' + i.title + '*';
      if (i.variant && i.variant.trim()) line += ' — ' + i.variant;
      line += '\n   الكمية: ' + i.qty + ' × ' + i.price.toFixed(2) + ' ' + CONFIG.currency;
      line += '\n   المجموع: *' + (i.price * i.qty).toFixed(2) + ' ' + CONFIG.currency + '*';
      return line;
    }).join('\n\n');

    var msg = '🛒 *طلب جديد من ' + CONFIG.storeName + '*\n\n'
      + '👤 *الاسم:* ' + name + '\n'
      + '📞 *الجوال:* ' + phone + emailStr + '\n'
      + '📍 *العنوان/الموقع:* ' + addr + '\n'
      + '💳 *الدفع:* ' + pay + '\n\n'
      + '*المنتجات:*\n' + lines + '\n\n'
      + '📦 *الشحن:* ' + (shipping === 0 ? 'مجاني' : shipping.toFixed(2) + ' ' + CONFIG.currency) + '\n'
      + '💰 *الإجمالي النهائي: ' + total.toFixed(2) + ' ' + CONFIG.currency + '*'
      + (notes ? '\n\n📝 *ملاحظات:* ' + notes : '');

    var order = { id: 'ORD-' + Date.now(), date: new Date().toLocaleDateString('ar-SA'), items: cart.slice(), total: total, status: 'جديد', name: name, phone: phone, addr: addr, pay: pay };
    orderHistory.unshift(order);
    if (orderHistory.length > 20) orderHistory.pop();
    saveHistory();

    window.open('https://wa.me/' + CONFIG.whatsapp + '?text=' + encodeURIComponent(msg), '_blank');
    cart = []; saveCart();
    checkoutFormVisible = false; checkoutPrefillAddr = null;
    closeCartSheet(); closeModal('cart-modal'); updateCartUI();
    toast('تم تحويلك للواتساب لإرسال الطلب! ✅', 'success');
    if (btn) { btn.innerHTML = orig; btn.disabled = false; btn.style.opacity = '1'; }
  }, 800);
}

function doCall()      { closeModal('contact-modal'); window.location.href = 'tel:' + CONFIG.phone; }
function doWhatsapp()  { closeModal('contact-modal'); window.open('https://wa.me/' + CONFIG.whatsapp + '?text=' + encodeURIComponent('مرحباً، لدي استفسار بخصوص المتجر.'), '_blank'); }

/* ============================================================
   GOOGLE AUTH
   ============================================================ */
function renderGoogleButton() {
  var container = document.getElementById('google-auth-container');
  if (!container) return;
  if (currentUser) { container.innerHTML = ''; return; }
  if (window.google && google.accounts && google.accounts.id) {
    try {
      google.accounts.id.initialize({ client_id: '360615303745-h45ri50dd4mlfarff2rbu2tivmho822u.apps.googleusercontent.com', callback: handleCredentialResponse });
      google.accounts.id.renderButton(container, { theme:'outline', size:'large', shape:'pill', width:250 });
    } catch(e) { container.innerHTML = '<span style="font-size:12px;color:var(--text-3)">تعذّر تحميل تسجيل الدخول</span>'; }
  } else { container.innerHTML = '<span style="font-size:12px;color:var(--text-3)">جاري تحميل تسجيل الدخول…</span>'; }
}

function handleCredentialResponse(response) {
  try {
    var payload = response.credential.split('.')[1];
    var data = JSON.parse(decodeURIComponent(atob(payload).split('').map(function(c) { return '%' + ('00' + c.charCodeAt(0).toString(16)).slice(-2); }).join('')));
    currentUser = { name: data.name, email: data.email, picture: data.picture };
    localStorage.setItem('sp_user_v5', JSON.stringify(currentUser));
    toast('تم تسجيل الدخول بنجاح ✅','success'); updateGreeting(); updateCartUI();
  } catch(e) { toast('حدث خطأ أثناء تسجيل الدخول','warn'); }
}

function logoutGoogle() {
  currentUser = null; localStorage.removeItem('sp_user_v5');
  updateGreeting(); toast('تم تسجيل الخروج','warn'); updateCartUI();
}

/* ============================================================
   WISHLIST
   ============================================================ */
function toggleWishlist(e, pid) {
  if (e) e.stopPropagation();
  var wasIn = wishlistSet.has(pid);
  if (wasIn) { wishlistSet.delete(pid); wishlist = wishlist.filter(function(id) { return id !== pid; }); toast('تمت الإزالة من المفضلة 🤍'); }
  else { wishlistSet.add(pid); wishlist.push(pid); toast('تمت الإضافة للمفضلة ❤️'); }
  saveWishlist(); updateWishlistBadge();
  var btn = document.querySelector('.wishlist-btn[data-pid="' + pid + '"]');
  if (btn) { btn.classList.toggle('active', !wasIn); btn.textContent = !wasIn ? '❤️' : '🤍'; }
  applyAllFilters();
}

function updateWishlistBadge() {
  var m = document.getElementById('wl-count-mobile');
  if (m) { m.textContent = wishlist.length; m.style.display = wishlist.length ? '' : 'none'; }
}

function renderWishlist() {
  var body = document.getElementById('wishlist-body'); if (!body) return;
  var items = products.filter(function(p) { return wishlistSet.has(p.id); });
  if (!items.length) { body.innerHTML = '<div class="empty-state" style="margin:12px"><div class="icon">🤍</div><h3>المفضلة فارغة</h3><p>أضف منتجاتك المفضلة هنا</p></div>'; return; }
  body.innerHTML = '<div class="wl-grid">' + items.map(function(p) {
    return '<div class="wl-card" onclick="openDrawer(\'' + p.id + '\');closeModal(\'wishlist-modal\')">'
      + '<img class="wl-img" loading="lazy" src="' + escapeHtml(p.image||'') + '" alt="' + escapeHtml(p.title) + '" onerror="this.src=\'https://placehold.co/80x80/f5f5f5/aaaaaa?text=Image+Error\'"/>'
      + '<div class="wl-title">' + escapeHtml(p.title) + '</div>'
      + '<div class="wl-price">' + formatPrice(p.price) + ' ' + CONFIG.currency + '</div>'
      + '<button class="btn-wl-remove" onclick="event.stopPropagation();toggleWishlist(null,\'' + p.id + '\')">إزالة ✕</button></div>';
  }).join('') + '</div>';
}

/* ============================================================
   ORDER HISTORY
   ============================================================ */
function renderHistory() {
  var body = document.getElementById('history-body'); if (!body) return;
  if (!orderHistory.length) { body.innerHTML = '<div class="empty-state"><div class="icon">🧾</div><h3>لا توجد طلبات</h3><p>طلباتك ستظهر هنا بعد إتمامها</p></div>'; return; }
  body.innerHTML = orderHistory.map(function(o) {
    return '<div class="history-order">'
      + '<div class="history-order-head"><div class="order-id">رقم الطلب<b>' + o.id + '</b></div><span class="order-status">' + o.status + '</span></div>'
      + '<div class="order-body-inner"><div class="order-date">📅 ' + o.date + ' · 💳 ' + o.pay + '</div>'
      + o.items.map(function(i) { return '<div class="order-item-line"><span>' + escapeHtml(i.title) + ' ×' + i.qty + '</span><span>' + (i.price*i.qty).toFixed(2) + ' ' + CONFIG.currency + '</span></div>'; }).join('')
      + '<div class="order-total-line"><span>الإجمالي</span><span>' + o.total.toFixed(2) + ' ' + CONFIG.currency + '</span></div>'
      + '<button class="order-reorder-btn" onclick="reorder(\'' + o.id + '\')">🔄 إعادة الطلب</button></div></div>';
  }).join('');
}

function reorder(oid) {
  var order = orderHistory.find(function(o) { return o.id === oid; }); if (!order) return;
  order.items.forEach(function(item) {
    var ex = cart.find(function(i) { return i.cid === item.cid; });
    if (ex) ex.qty += item.qty; else cart.push(Object.assign({}, item));
  });
  saveCart(); updateCartUI(); closeModal('history-modal'); toast('تمت إضافة المنتجات للسلة ✅','success');
}

/* ============================================================
   MODAL SYSTEM (iOS-safe scroll lock)
   ============================================================ */
var savedScrollY = 0;

function openModal(id) {
  var m = document.getElementById(id); if (!m) return;
  if (id === 'wishlist-modal') renderWishlist();
  if (id === 'history-modal') renderHistory();
  if (id === 'cart-modal') renderCartBody(cart.reduce(function(s,i) { return s+i.price*i.qty; }, 0));
  m.style.display = 'flex';
  requestAnimationFrame(function() { m.classList.add('show'); });
  if (!document.body.classList.contains('modal-open')) {
    savedScrollY = window.scrollY || window.pageYOffset;
    document.body.classList.add('modal-open');
    document.body.style.position = 'fixed';
    document.body.style.top = '-' + savedScrollY + 'px';
    document.body.style.width = '100%';
  }
}

function closeModal(id) {
  var m = document.getElementById(id); if (!m) return;
  m.classList.remove('show');
  if (id === 'product-modal') drawerOpen = false;
  if (id === 'cart-modal') { checkoutFormVisible = false; checkoutPrefillAddr = null; }
  setTimeout(function() {
    m.style.display = 'none';
    if (!document.querySelector('.modal.show')) {
      document.body.classList.remove('modal-open');
      document.body.style.position = '';
      document.body.style.top = '';
      document.body.style.width = '';
      window.scrollTo(0, savedScrollY);
    }
  }, 320);
}

function backdropClose(e, id) { if (e.target === e.currentTarget) closeModal(id); }

document.addEventListener('keydown', function(e) {
  if (e.key === 'Escape') {
    var cs = document.getElementById('cart-sheet'); if (cs && cs.classList.contains('show')) closeCartSheet();
    ['product-modal','cart-modal','wishlist-modal','history-modal','contact-modal','address-modal','first-visit-modal','add-addr-modal','maps-picker-modal','addr-select-modal']
      .forEach(function(id) { var m = document.getElementById(id); if (m && m.classList.contains('show')) closeModal(id); });
    var zo = document.getElementById('zoom-overlay'); if (zo && zo.classList.contains('active')) closeZoom();
  }
  var zo = document.getElementById('zoom-overlay');
  if (zo && zo.classList.contains('active')) {
    if (e.key === '+' || e.key === '=') doZoom(1);
    if (e.key === '-') doZoom(-1);
    if (e.key === '0') resetZoom();
  }
});

/* ============================================================
   ZOOM LIGHTBOX
   ============================================================ */
var zScale=1, zTx=0, zTy=0, zDragging=false, zDx=0, zDy=0, zLtx=0, zLty=0;
var ZMIN=1, ZMAX=5, ZSTEP=0.4;

function initZoom() {
  var zImg = document.getElementById('zoom-img');
  var zOv  = document.getElementById('zoom-overlay');
  if (!zImg || !zOv) return;
  zImg.addEventListener('mousedown', function(e) { if (zScale<=1) return; zDragging=true; zDx=e.clientX-zLtx; zDy=e.clientY-zLty; zImg.classList.add('drag'); e.preventDefault(); });
  document.addEventListener('mousemove', function(e) { if (!zDragging) return; zTx=e.clientX-zDx; zTy=e.clientY-zDy; zLtx=zTx; zLty=zTy; applyZoomTransform(); });
  document.addEventListener('mouseup', function() { zDragging=false; zImg.classList.remove('drag'); });
  zImg.addEventListener('dblclick', function() { zScale===1 ? doZoom(1) : resetZoom(); });
  var lastTap=0;
  zImg.addEventListener('touchend', function() { var now=Date.now(); if(now-lastTap<300) zScale===1?doZoom(1):resetZoom(); lastTap=now; });
  zImg.addEventListener('touchstart', function(e) { if(e.touches.length===1&&zScale>1) { zDragging=true; zDx=e.touches[0].clientX-zLtx; zDy=e.touches[0].clientY-zLty; } }, {passive:true});
  zImg.addEventListener('touchmove', function(e) { if(!zDragging||e.touches.length!==1) return; zTx=e.touches[0].clientX-zDx; zTy=e.touches[0].clientY-zDy; zLtx=zTx; zLty=zTy; applyZoomTransform(); }, {passive:true});
  zImg.addEventListener('touchend', function() { zDragging=false; });
  zOv.addEventListener('wheel', function(e) { e.preventDefault(); doZoom(e.deltaY<0?1:-1); }, {passive:false});
  zOv.addEventListener('click', function(e) { if(e.target===zOv||e.target===document.getElementById('zoom-container')) closeZoom(); });
}

function openZoom(src) {
  zScale=1; zTx=0; zTy=0; zLtx=0; zLty=0;
  var img = document.getElementById('zoom-img'); if(!img) return;
  img.src=src; applyZoomTransform();
  var ov = document.getElementById('zoom-overlay');
  ov.style.display='flex'; requestAnimationFrame(function() { ov.classList.add('active'); });
}
function closeZoom() {
  var ov = document.getElementById('zoom-overlay');
  ov.classList.add('fading');
  setTimeout(function() { ov.classList.remove('active','fading'); ov.style.display='none'; var img=document.getElementById('zoom-img'); if(img) img.src=''; }, 280);
}
function applyZoomTransform() {
  var img = document.getElementById('zoom-img'); if(!img) return;
  img.style.transform = 'scale(' + zScale + ') translate(' + zTx/zScale + 'px,' + zTy/zScale + 'px)';
  var pct = document.getElementById('zoom-pct'); if(pct) pct.textContent = Math.round(zScale*100) + '%';
}
function doZoom(dir) { zScale=Math.min(ZMAX,Math.max(ZMIN,parseFloat((zScale+dir*ZSTEP).toFixed(2)))); if(zScale===ZMIN){zTx=0;zTy=0;} applyZoomTransform(); }
function resetZoom()  { zScale=1; zTx=0; zTy=0; applyZoomTransform(); }

/* ============================================================
   TOAST
   ============================================================ */
function toast(msg, type, durationInSeconds) {
  var wrap = document.getElementById('toast-wrap'); if(!wrap) return;
  var ms = durationInSeconds ? durationInSeconds * 1000 : 3000;
  var t = document.createElement('div');
  t.className = 'toast ' + (type||'');
  t.innerHTML = msg;
  wrap.appendChild(t);
  var removed = false;
  var remove = function() { if(removed) return; removed=true; t.remove(); document.removeEventListener('click',remove); document.removeEventListener('touchstart',remove); };
  setTimeout(remove, ms);
  setTimeout(function() { document.addEventListener('click',remove); document.addEventListener('touchstart',remove,{passive:true}); }, 50);
}


/* showCheckoutForm kept for backward compatibility */
function showCheckoutForm() { showCheckoutFlow(); }

